export const BODY = {"level-4":{"id":"level-4","kind":"level","level":4,"src":"level:4","title":"Level 4 · Tables to Twelve","body":"All the tables to twelve with their shortcuts, short division, factor pairs, tenths and hundredths, mixed numbers, area, and naming triangles and quadrilaterals.","route":"#/atlas","cta":"See the road"},"land-l4-muldiv":{"id":"land-l4-muldiv","kind":"land","level":4,"src":"land:l4-muldiv","title":"Mental maths shortcuts — in The Times Market","body":"6 stops on this stretch of the road: Split the hard one · Eleven times a two-digit number · Times 25 is a quarter of 100 · Halve one, double the other · Taking from 1000 · Short division.","art":"art/w-market.webp","route":"#/world/market","cta":"Visit Market"},"land-l4-factors":{"id":"land-l4-factors","kind":"land","level":4,"src":"land:l4-factors","title":"Factor pairs — in The Factor Forest","body":"3 stops on this stretch of the road: Factors come in pairs · The next multiple · Tests for 2, 5 and 10.","art":"art/w-forest.webp","route":"#/world/forest","cta":"Visit Forest"},"land-l4-fractions":{"id":"land-l4-fractions","kind":"land","level":4,"src":"land:l4-fractions","title":"Fractions and tenths — in The Fraction Bakery","body":"5 stops on this stretch of the road: A fraction of an amount · Simplest form · Mixed numbers and top-heavy fractions · Tenths and hundredths · × and ÷ by 10, 100, 1000.","art":"art/w-bakery.webp","route":"#/world/bakery","cta":"Visit Bakery"},"land-l4-money":{"id":"land-l4-money","kind":"land","level":4,"src":"land:l4-money","title":"Spending, saving and time — in Coin Street","body":"4 stops on this stretch of the road: Giving change · The 24-hour clock · What is left? · Saving for something.","art":"art/w-coinstreet.webp","route":"#/world/coinstreet","cta":"Visit Coins"},"land-l4-shape":{"id":"land-l4-shape","kind":"land","level":4,"src":"land:l4-shape","title":"Shapes, grids and area — in Shape City","body":"4 stops on this stretch of the road: Kinds of triangle · Four-sided shapes · Coordinates and moves · Area of a rectangle.","art":"art/w-shapecity.webp","route":"#/world/shapecity","cta":"Visit Shape City"},"land-l4-contest":{"id":"land-l4-contest","kind":"land","level":4,"src":"land:l4-contest","title":"Ways into a problem — in The Strategy School","body":"5 stops on this stretch of the road: Work backwards · Guess, check, improve · Make a table · Draw the bars · Ride the cycle.","art":"art/w-strategy.webp","route":"#/world/strategy","cta":"Visit Strategy"},"hook-times-twelve-hook":{"id":"hook-times-twelve-hook","kind":"hook","src":"stop:times-twelve#hook","title":"Can you? — Split the hard one","body":"7 × 12 — twelve is the table nobody likes.","cta":"Find out how","level":4,"route":"#/stop/times-twelve"},"why-times-twelve-why1":{"id":"why-times-twelve-why1","kind":"why","src":"stop:times-twelve#why1","title":"Why “Split the hard one” works","body":"Draw it as a rectangle 7 tall and 12 wide, cut it at 10, and the two pieces are the two easy sums.","cta":"See why","level":4,"route":"#/stop/times-twelve"},"moment-times-twelve-beat4":{"id":"moment-times-twelve-beat4","kind":"moment","src":"story:times-twelve#beat4","badge":{"id":"story","label":"A story"},"title":"Boxes of a dozen — on the notepad","body":"Ines: …and seven twos. 7 × 2 = 14","cta":"Read the story","level":4,"route":"#/stop/times-twelve"},"try-times-twelve-L4":{"id":"try-times-twelve-L4","kind":"try","level":4,"src":"try:times-twelve@4/2#0","title":"Split the hard one — your turn","route":"#/stop/times-twelve","cta":"Practise this stop","play":{"q":"13 × 12 = ?","opts":["156","130","26"],"after":"Twelve is ten and two. Do each, then add."}},"trick-times-eleven-idea":{"id":"trick-times-eleven-idea","kind":"trick","src":"stop:times-eleven#idea","title":"Eleven times a two-digit number","body":"Split the digits apart and put their sum in the middle. 43 × 11 is 43 × 10 plus 43: 430 + 43. Line them up and the middle column is 3 + 4 — the two digits added.","cta":"Learn the trick","level":4,"route":"#/stop/times-eleven"},"story-times-eleven-open":{"id":"story-times-eleven-open","kind":"story","src":"story:times-eleven#open","badge":{"id":"story","label":"A story"},"title":"The carriage game","body":"On the train to see their grandmother, Kwame and Pip play a game: multiply the carriage number by 11. — with Kwame and Pip.","art":"art/s-train.webp","cta":"Read the story","level":4,"route":"#/stop/times-eleven"},"hook-times-eleven-hook":{"id":"hook-times-eleven-hook","kind":"hook","src":"stop:times-eleven#hook","title":"Can you? — Eleven times a two-digit number","body":"43 × 11 — in two seconds.","cta":"Find out how","level":4,"route":"#/stop/times-eleven"},"idea-times-eleven-case0":{"id":"idea-times-eleven-case0","kind":"idea","src":"stop:times-eleven#case0","title":"Eleven times a two-digit number: The digits add to under 10","body":"Pull the two digits apart and drop their sum in the gap between them.","cta":"See it worked","level":4,"route":"#/stop/times-eleven"},"worked-times-eleven-worked0":{"id":"worked-times-eleven-worked0","kind":"worked","src":"stop:times-eleven#worked0","title":"Worked out — Eleven times a two-digit number: The digits add to under 10","body":"43 × 11: 4 + 3 — the middle → 7 · 4 … 7 … 3 → 473","cta":"Watch it step by step","level":4,"route":"#/stop/times-eleven"},"idea-times-eleven-case1":{"id":"idea-times-eleven-case1","kind":"idea","src":"stop:times-eleven#case1","title":"Eleven times a two-digit number: The middle carries","body":"When the two digits make 10 or more, only the ones of that sum go in the middle. The ten carries into the front digit.","cta":"See it worked","level":4,"route":"#/stop/times-eleven"},"worked-times-eleven-worked1":{"id":"worked-times-eleven-worked1","kind":"worked","src":"stop:times-eleven#worked1","title":"Worked out — Eleven times a two-digit number: The middle carries","body":"78 × 11: 7 + 8 — the middle → 15 · 7 … 15 … 8 (carry the one) → 858","cta":"Watch it step by step","level":4,"route":"#/stop/times-eleven"},"idea-times-eleven-case2":{"id":"idea-times-eleven-case2","kind":"idea","src":"stop:times-eleven#case2","title":"Eleven times a two-digit number: A three-digit number","body":"The split-apart trick gets messy here, so use the reason behind it: eleven lots is ten lots and one more lot.","cta":"See it worked","level":4,"route":"#/stop/times-eleven"},"worked-times-eleven-worked2":{"id":"worked-times-eleven-worked2","kind":"worked","src":"stop:times-eleven#worked2","title":"Worked out — Eleven times a two-digit number: A three-digit number","body":"234 × 11: 234 × 10 → 2340 · Add 234 → 2574","cta":"Watch it step by step","level":4,"route":"#/stop/times-eleven"},"why-times-eleven-why1":{"id":"why-times-eleven-why1","kind":"why","src":"stop:times-eleven#why1","title":"Why “Eleven times a two-digit number” works","body":"If the two digits add up to 10 or more, the middle carries one into the hundreds: 78 × 11 is 7, then 15, then 8 — so 858.","cta":"See why","level":4,"route":"#/stop/times-eleven"},"why-times-eleven-why2":{"id":"why-times-eleven-why2","kind":"why","src":"stop:times-eleven#why2","title":"Why “Eleven times a two-digit number” works","body":"A three-digit number goes back to where the trick came from: times ten, then add the number once more. 234 × 11 = 2340 + 234 = 2574.","cta":"See why","level":4,"route":"#/stop/times-eleven"},"algebra-times-eleven-alg":{"id":"algebra-times-eleven-alg","kind":"algebra","src":"stop:times-eleven#alg","title":"The algebra behind “Eleven times a two-digit number”","body":"(10a + b) × 11 = 100a + 10(a + b) + b","cta":"See why","level":4,"route":"#/stop/times-eleven"},"moment-times-eleven-beat3":{"id":"moment-times-eleven-beat3","kind":"moment","src":"story:times-eleven#beat3","badge":{"id":"story","label":"A story"},"title":"The carriage game — on the notepad","body":"Kwame: Four, seven, three. 43 × 11 = 473","cta":"Read the story","level":4,"route":"#/stop/times-eleven"},"moral-times-eleven-beat6":{"id":"moral-times-eleven-beat6","kind":"moral","src":"story:times-eleven#beat6","badge":{"id":"story","label":"A story"},"title":"Pip, in “The carriage game”","body":"That is my new party trick.","cta":"Read the story","level":4,"route":"#/stop/times-eleven"},"try-times-eleven-L4":{"id":"try-times-eleven-L4","kind":"try","level":4,"src":"try:times-eleven@4/1#0","title":"Eleven times a two-digit number — your turn","route":"#/stop/times-eleven","cta":"Practise this stop","play":{"q":"40 × 11 = ?","opts":["440","4","441"],"after":"Split the digits apart and put their sum in the middle."}},"trick-short-division-idea":{"id":"trick-short-division-idea","kind":"trick","src":"stop:short-division#idea","title":"Short division","body":"Divide one place at a time from the left. Whatever will not share carries into the next place as tens; whatever is left at the very end is the remainder. Sharing 347 between 5 is sharing 3 hundreds, 4 tens and 7 ones. 3 hundreds will not go into 5 groups as whole hundreds, so break them into 30 tens. Now there are 34 tens, and 5 groups get 6 tens each, with 4 tens over.","cta":"Learn the trick","level":4,"route":"#/stop/short-division"},"story-short-division-open":{"id":"story-short-division-open","kind":"story","src":"story:short-division#open","badge":{"id":"story","label":"A story"},"title":"Packing the boxes","body":"347 old books are going to a school, packed 5 to a box. — with Suki and Ines.","art":"art/s-library.webp","cta":"Read the story","level":4,"route":"#/stop/short-division"},"hook-short-division-hook":{"id":"hook-short-division-hook","kind":"hook","src":"stop:short-division#hook","title":"Can you? — Short division","body":"347 ÷ 5 — and it will not come out exactly.","cta":"Find out how","level":4,"route":"#/stop/short-division"},"idea-short-division-case0":{"id":"idea-short-division-case0","kind":"idea","src":"stop:short-division#case0","title":"Short division: How many whole ones?","body":"Divide place by place from the left, passing on what does not share. The digits along the top are the answer.","cta":"See it worked","level":4,"route":"#/stop/short-division"},"worked-short-division-worked0":{"id":"worked-short-division-worked0","kind":"worked","src":"stop:short-division#worked0","title":"Worked out — Short division: How many whole ones?","body":"347 ÷ 5: how many whole 5s? (leave out the remainder): 34 ÷ 5 — how many 5s fit? → 6 · 47 ÷ 5 — how many 5s fit? → 9 · Read the digits along the top → 69","cta":"Watch it step by step","level":4,"route":"#/stop/short-division"},"idea-short-division-case1":{"id":"idea-short-division-case1","kind":"idea","src":"stop:short-division#case1","title":"Short division: A place that will not share","body":"Sometimes a place is too small to give every group even one. Write 0 on top — do not skip it — and pass it all on.","cta":"See it worked","level":4,"route":"#/stop/short-division"},"worked-short-division-worked1":{"id":"worked-short-division-worked1","kind":"worked","src":"stop:short-division#worked1","title":"Worked out — Short division: A place that will not share","body":"823 ÷ 4: how many whole 4s? (leave out the remainder): 8 ÷ 4 — how many 4s fit? → 2 · 2 ÷ 4 — how many 4s fit? → 0 · 23 ÷ 4 — how many 4s fit? → 5 · Read the digits along the top → 205","cta":"Watch it step by step","level":4,"route":"#/stop/short-division"},"idea-short-division-case2":{"id":"idea-short-division-case2","kind":"idea","src":"stop:short-division#case2","title":"Short division: What is left over?","body":"Now the question is the remainder: what is still left after the very last place has been shared.","cta":"See it worked","level":4,"route":"#/stop/short-division"},"worked-short-division-worked2":{"id":"worked-short-division-worked2","kind":"worked","src":"stop:short-division#worked2","title":"Worked out — Short division: What is left over?","body":"257 ÷ 6: what is the remainder?: 25 ÷ 6 — how many 6s fit? → 4 · 17 ÷ 6 — how many 6s fit? → 2 · What is left at the end? 17 − 6 × 2 → 5","cta":"Watch it step by step","level":4,"route":"#/stop/short-division"},"why-short-division-why1":{"id":"why-short-division-why1","kind":"why","src":"stop:short-division#why1","title":"Why “Short division” works","body":"Those 4 tens become 40 ones, which join the 7 ones: 47. Each group gets 9 more, with 2 left over. The digits you wrote on top — 6 tens and 9 ones — are the answer, 69, and the 2 that could not be shared is the remainder.","cta":"See why","level":4,"route":"#/stop/short-division"},"why-short-division-why2":{"id":"why-short-division-why2","kind":"why","src":"stop:short-division#why2","title":"Why “Short division” works","body":"It is the same exchange as column subtraction, run from the left: what does not fit in one place is passed on, ten times bigger, to the place on its right. You can check it: 69 × 5 + 2 = 347.","cta":"See why","level":4,"route":"#/stop/short-division"},"why-short-division-why3":{"id":"why-short-division-why3","kind":"why","src":"stop:short-division#why3","title":"Why “Short division” works","body":"If a place is too small to share at all, the answer still needs a digit there: 823 ÷ 4 — 8 hundreds give 2, but 2 tens will not give 4 groups a ten each, so write 0 and pass on 20 ones. 23 ones give 5, with 3 over: 205, remainder 3.","cta":"See why","level":4,"route":"#/stop/short-division"},"algebra-short-division-alg":{"id":"algebra-short-division-alg","kind":"algebra","src":"stop:short-division#alg","title":"The algebra behind “Short division”","body":"n = d × q + r, with 0 ≤ r < d","cta":"See why","level":4,"route":"#/stop/short-division"},"moment-short-division-beat3":{"id":"moment-short-division-beat3","kind":"moment","src":"story:short-division#beat3","badge":{"id":"story","label":"A story"},"title":"Packing the boxes — on the notepad","body":"Ines: Those 4 tens join the 7 ones: 47. That makes 9 fives, with some over. 47 − 5 × 9 = 2","cta":"Read the story","level":4,"route":"#/stop/short-division"},"moral-short-division-beat4":{"id":"moral-short-division-beat4","kind":"moral","src":"story:short-division#beat4","badge":{"id":"story","label":"A story"},"title":"Suki, in “Packing the boxes”","body":"So 69 full boxes, and 2 books left over for the class shelf.","cta":"Read the story","level":4,"route":"#/stop/short-division"},"try-short-division-L4":{"id":"try-short-division-L4","kind":"try","level":4,"src":"try:short-division@4/1#0","title":"Short division — your turn","route":"#/stop/short-division","cta":"Practise this stop","play":{"q":"41 ÷ 5: how many whole 5s? (leave out the remainder) = ?","opts":["8","9","7"],"after":"Divide one place at a time from the left. Whatever will not share carries into the next place as tens; whatever is left at the very end is the remainder."}},"idea-giving-change-case0":{"id":"idea-giving-change-case0","kind":"idea","src":"stop:giving-change#case0","title":"Giving change: Buying one thing","body":"Count up from the price: to the next ten first, then on to what you paid. The jumps added together are the change.","cta":"See it worked","level":4,"route":"#/stop/giving-change"},"worked-giving-change-worked1":{"id":"worked-giving-change-worked1","kind":"worked","src":"stop:giving-change#worked1","title":"Worked out — Giving change: Buying several","body":"You buy 4 kites at 18 coins each and pay with 100 coins. How many coins do you get back?: The total: 4 × 18 → 72 · 72 up to 80 → 8 · 80 up to 100 → 20 · Add the jumps: your change → 28","cta":"Watch it step by step","level":4,"route":"#/stop/giving-change"},"algebra-giving-change-alg":{"id":"algebra-giving-change-alg","kind":"algebra","src":"stop:giving-change#alg","title":"The algebra behind “Giving change”","body":"change = paid − price = (next ten − price) + (paid − next ten)","cta":"See why","level":4,"route":"#/stop/giving-change"},"try-giving-change-L4":{"id":"try-giving-change-L4","kind":"try","level":4,"src":"try:giving-change@4/3#0","title":"Giving change — your turn","route":"#/stop/giving-change","cta":"Practise this stop","play":{"q":"You buy 2 mangos at 36 coins each and pay with 100 coins. How many coins do you get back?","opts":["28","72","8"],"after":"Count UP from the price to what you paid — to the next ten first, then on. The jumps are the change."}},"trick-twenty-four-hour-idea":{"id":"trick-twenty-four-hour-idea","kind":"trick","src":"stop:twenty-four-hour#idea","title":"The 24-hour clock","body":"After midday, add 12 to the hour to get the 24-hour time; take 12 away to get back. Midnight is 00. A day has 24 hours but an ordinary clock face only shows 12, so every time happens twice — 7:45 in the morning and 7:45 in the evening. Writing am or pm says which. The 24-hour clock does it with the number itself: it simply keeps counting past 12 instead of starting again.","cta":"Learn the trick","level":4,"route":"#/stop/twenty-four-hour"},"story-twenty-four-hour-open":{"id":"story-twenty-four-hour-open","kind":"story","src":"story:twenty-four-hour#open","badge":{"id":"story","label":"A story"},"title":"The evening train","body":"At the bus station, the board says the last bus leaves at 19:45. — with Suki and Dax.","art":"art/s-bus.webp","cta":"Read the story","level":4,"route":"#/stop/twenty-four-hour"},"hook-twenty-four-hour-hook":{"id":"hook-twenty-four-hour-hook","kind":"hook","src":"stop:twenty-four-hour#hook","title":"Can you? — The 24-hour clock","body":"A train timetable says 19:45. Is that before or after your tea?","cta":"Find out how","level":4,"route":"#/stop/twenty-four-hour"},"idea-twenty-four-hour-case0":{"id":"idea-twenty-four-hour-case0","kind":"idea","src":"stop:twenty-four-hour#case0","title":"The 24-hour clock: pm into 24-hour","body":"After midday the 24-hour clock keeps counting past 12, so add 12 to the hour.","cta":"See it worked","level":4,"route":"#/stop/twenty-four-hour"},"worked-twenty-four-hour-worked0":{"id":"worked-twenty-four-hour-worked0","kind":"worked","src":"stop:twenty-four-hour#worked0","title":"Worked out — The 24-hour clock: pm into 24-hour","body":"Write 7:45 pm in the 24-hour clock.: Is it after midday (pm)? → Yes · 7 + 12 → 19 · So it is → 19:45","cta":"Watch it step by step","level":4,"route":"#/stop/twenty-four-hour"},"idea-twenty-four-hour-case1":{"id":"idea-twenty-four-hour-case1","kind":"idea","src":"stop:twenty-four-hour#case1","title":"The 24-hour clock: am into 24-hour","body":"Before midday nothing is added — the hour stays, with a 0 in front if it is a single digit.","cta":"See it worked","level":4,"route":"#/stop/twenty-four-hour"},"worked-twenty-four-hour-worked1":{"id":"worked-twenty-four-hour-worked1","kind":"worked","src":"stop:twenty-four-hour#worked1","title":"Worked out — The 24-hour clock: am into 24-hour","body":"Write 9:15 am in the 24-hour clock.: Is it after midday (pm)? → No · Before midday the hour stays → 9 · So it is → 09:15","cta":"Watch it step by step","level":4,"route":"#/stop/twenty-four-hour"},"idea-twenty-four-hour-case2":{"id":"idea-twenty-four-hour-case2","kind":"idea","src":"stop:twenty-four-hour#case2","title":"The 24-hour clock: 24-hour into pm","body":"An hour of 13 or more is in the afternoon or evening: take 12 away and write pm.","cta":"See it worked","level":4,"route":"#/stop/twenty-four-hour"},"worked-twenty-four-hour-worked2":{"id":"worked-twenty-four-hour-worked2","kind":"worked","src":"stop:twenty-four-hour#worked2","title":"Worked out — The 24-hour clock: 24-hour into pm","body":"Write 16:30 in the 12-hour clock, with am or pm.: Is the hour 12 or more (pm)? → Yes · 16 − 12 → 4 · So it is → 4:30 pm","cta":"Watch it step by step","level":4,"route":"#/stop/twenty-four-hour"},"idea-twenty-four-hour-case3":{"id":"idea-twenty-four-hour-case3","kind":"idea","src":"stop:twenty-four-hour#case3","title":"The 24-hour clock: 24-hour into am","body":"An hour from 01 to 11 is the morning: the hour stays as it is, and you write am.","cta":"See it worked","level":4,"route":"#/stop/twenty-four-hour"},"worked-twenty-four-hour-worked3":{"id":"worked-twenty-four-hour-worked3","kind":"worked","src":"stop:twenty-four-hour#worked3","title":"Worked out — The 24-hour clock: 24-hour into am","body":"Write 08:20 in the 12-hour clock, with am or pm.: Is the hour 12 or more (pm)? → No · The hour stays → 8 · So it is → 8:20 am","cta":"Watch it step by step","level":4,"route":"#/stop/twenty-four-hour"},"idea-twenty-four-hour-case4":{"id":"idea-twenty-four-hour-case4","kind":"idea","src":"stop:twenty-four-hour#case4","title":"The 24-hour clock: Midday: 12","body":"Midday is the odd one: 12 in both clocks, and it is already pm — nothing is added or taken away.","cta":"See it worked","level":4,"route":"#/stop/twenty-four-hour"},"idea-twenty-four-hour-case5":{"id":"idea-twenty-four-hour-case5","kind":"idea","src":"stop:twenty-four-hour#case5","title":"The 24-hour clock: Midnight: 00","body":"Midnight starts a new day, so the 24-hour count starts again from 00. 12:30 at night is 00:30.","cta":"See it worked","level":4,"route":"#/stop/twenty-four-hour"},"worked-twenty-four-hour-worked5":{"id":"worked-twenty-four-hour-worked5","kind":"worked","src":"stop:twenty-four-hour#worked5","title":"Worked out — The 24-hour clock: Midnight: 00","body":"Write 12:30 am in the 24-hour clock.: Is it after midday (pm)? → No · 12 at night starts the day again: the hour is → 0 · So it is → 00:30","cta":"Watch it step by step","level":4,"route":"#/stop/twenty-four-hour"},"why-twenty-four-hour-why1":{"id":"why-twenty-four-hour-why1","kind":"why","src":"stop:twenty-four-hour#why1","title":"Why “The 24-hour clock” works","body":"So the afternoon hours carry on 13, 14, 15… 1 pm is 13:00 because it is 12 hours plus 1. That is why you add 12 to any pm hour — and take 12 away to go back. Morning hours need nothing added: 9:15 am is 09:15, with a 0 in front so every time has two digits for the hour.","cta":"See why","level":4,"route":"#/stop/twenty-four-hour"},"why-twenty-four-hour-why2":{"id":"why-twenty-four-hour-why2","kind":"why","src":"stop:twenty-four-hour#why2","title":"Why “The 24-hour clock” works","body":"The two odd ones are the twelves. Midday is 12:00 in both. Midnight starts a new day, so the count starts again from nothing: 12:30 am is 00:30.","cta":"See why","level":4,"route":"#/stop/twenty-four-hour"},"algebra-twenty-four-hour-alg":{"id":"algebra-twenty-four-hour-alg","kind":"algebra","src":"stop:twenty-four-hour#alg","title":"The algebra behind “The 24-hour clock”","body":"pm: H = h + 12 (except 12 pm = 12) · am: H = h (except 12 am = 00)","cta":"See why","level":4,"route":"#/stop/twenty-four-hour"},"moment-twenty-four-hour-beat4":{"id":"moment-twenty-four-hour-beat4","kind":"moment","src":"story:twenty-four-hour#beat4","badge":{"id":"story","label":"A story"},"title":"The evening train — on the notepad","body":"Suki: And going the other way, 3 pm is 3 hours after midday. 3 + 12 = 15","cta":"Read the story","level":4,"route":"#/stop/twenty-four-hour"},"moral-twenty-four-hour-beat5":{"id":"moral-twenty-four-hour-beat5","kind":"moral","src":"story:twenty-four-hour#beat5","badge":{"id":"story","label":"A story"},"title":"Dax, in “The evening train”","body":"So 3 pm is 15:00, and our bus is at 7:45 pm.","cta":"Read the story","level":4,"route":"#/stop/twenty-four-hour"},"try-twenty-four-hour-L4":{"id":"try-twenty-four-hour-L4","kind":"try","level":4,"src":"try:twenty-four-hour@4/1#0","title":"The 24-hour clock — your turn","route":"#/stop/twenty-four-hour","cta":"Practise this stop","play":{"q":"Write 7:35 pm in the 24-hour clock.","opts":["19:35","17:35","21:35"],"after":"After midday, add 12 to the hour to get the 24-hour time; take 12 away to get back. Midnight is 00."}},"trick-area-rectangles-idea":{"id":"trick-area-rectangles-idea","kind":"trick","src":"stop:area-rectangles#idea","title":"Area of a rectangle","body":"Area is how many unit squares cover a shape. A rectangle is rows of equal squares, so area = length × width. Area measures how much surface a shape covers, and we measure it in squares: a square 1 cm on each side is 1 square centimetre, written 1 cm².","cta":"Learn the trick","level":4,"route":"#/stop/area-rectangles"},"story-area-rectangles-open":{"id":"story-area-rectangles-open","kind":"story","src":"story:area-rectangles#open","badge":{"id":"story","label":"A story"},"title":"The new rug","body":"Dax's family has a new rug with a square pattern: 7 squares long and 6 squares wide. — with Mira and Dax.","art":"art/s-room.webp","cta":"Read the story","level":4,"route":"#/stop/area-rectangles"},"idea-area-rectangles-case0":{"id":"idea-area-rectangles-case0","kind":"idea","src":"stop:area-rectangles#case0","title":"Area of a rectangle: Counting shaded squares","body":"No need to count one by one: count the squares in one row, count the rows, and multiply.","cta":"See it worked","level":4,"route":"#/stop/area-rectangles"},"worked-area-rectangles-worked1":{"id":"worked-area-rectangles-worked1","kind":"worked","src":"stop:area-rectangles#worked1","title":"Worked out — Area of a rectangle: Length × width","body":"A rectangle is 7 cm long and 6 cm wide. What is its area, in cm²?: Squares in one row → 7 · Number of rows → 6 · 7 × 6 → 42","cta":"Watch it step by step","level":4,"route":"#/stop/area-rectangles"},"worked-area-rectangles-worked2":{"id":"worked-area-rectangles-worked2","kind":"worked","src":"stop:area-rectangles#worked2","title":"Worked out — Area of a rectangle: Finding a missing side","body":"A rectangle has an area of 42 cm² and a length of 7 cm. How wide is it, in cm?: The area → 42 · Rows of 7: 42 ÷ 7 → 6","cta":"Watch it step by step","level":4,"route":"#/stop/area-rectangles"},"why-area-rectangles-why2":{"id":"why-area-rectangles-why2","kind":"why","src":"stop:area-rectangles#why2","title":"Why “Area of a rectangle” works","body":"That also works backwards. If you know the area and one side, the other side is how many equal rows fit: area ÷ the side you know.","cta":"See why","level":4,"route":"#/stop/area-rectangles"},"moment-area-rectangles-beat4":{"id":"moment-area-rectangles-beat4","kind":"moment","src":"story:area-rectangles#beat4","badge":{"id":"story","label":"A story"},"title":"The new rug — on the notepad","body":"Mira: Six equal rows of seven is a times table. 6 × 7 = 42","cta":"Read the story","level":4,"route":"#/stop/area-rectangles"},"hook-fraction-of-amount-hook":{"id":"hook-fraction-of-amount-hook","kind":"hook","src":"stop:fraction-of-amount#hook","title":"Can you? — A fraction of an amount","body":"3/4 of 20 — without drawing twenty things?","cta":"Find out how","level":4,"route":"#/stop/fraction-of-amount"},"worked-fraction-of-amount-worked0":{"id":"worked-fraction-of-amount-worked0","kind":"worked","src":"stop:fraction-of-amount#worked0","title":"Worked out — A fraction of an amount: One share: 1/4 of","body":"1/4 of 12: How many equal shares? → 4 · 12 ÷ 4 → 3","cta":"Watch it step by step","level":4,"route":"#/stop/fraction-of-amount"},"worked-fraction-of-amount-worked1":{"id":"worked-fraction-of-amount-worked1","kind":"worked","src":"stop:fraction-of-amount#worked1","title":"Worked out — A fraction of an amount: Several shares: 3/4 of","body":"3/4 of 20: One share: 20 ÷ 4 → 5 · 3 shares: × 3 → 15","cta":"Watch it step by step","level":4,"route":"#/stop/fraction-of-amount"},"why-fraction-of-amount-why2":{"id":"why-fraction-of-amount-why2","kind":"why","src":"stop:fraction-of-amount#why2","title":"Why “A fraction of an amount” works","body":"That is why the order is \"divide, then multiply\": you cannot know what three quarters is until you know what one quarter is.","cta":"See why","level":4,"route":"#/stop/fraction-of-amount"},"moment-fraction-of-amount-beat4":{"id":"moment-fraction-of-amount-beat4","kind":"moment","src":"story:fraction-of-amount#beat4","badge":{"id":"story","label":"A story"},"title":"Sharing the laddoos — on the notepad","body":"Ines: Three piles of five. 5 × 3 = 15","cta":"Read the story","level":4,"route":"#/stop/fraction-of-amount"},"try-fraction-of-amount-L4":{"id":"try-fraction-of-amount-L4","kind":"try","level":4,"src":"try:fraction-of-amount@4/2#0","title":"A fraction of an amount — your turn","route":"#/stop/fraction-of-amount","cta":"Practise this stop","play":{"q":"3/4 of 20 = ?","opts":["15","5","16"],"after":"Divide by the bottom to find one share, then multiply by the top."}},"trick-simplify-fractions-idea":{"id":"trick-simplify-fractions-idea","kind":"trick","src":"stop:simplify-fractions#idea","title":"Simplest form","body":"Find the biggest number that divides the top and the bottom, and divide both by it. Simplifying is equivalent fractions run backwards: gluing small slices back into bigger ones. 12/16 of a tray of brownies is the same brownie as 3/4 — you have just stopped cutting so finely.","cta":"Learn the trick","level":4,"route":"#/stop/simplify-fractions"},"story-simplify-fractions-open":{"id":"story-simplify-fractions-open","kind":"story","src":"story:simplify-fractions#open","badge":{"id":"story","label":"A story"},"title":"The brownie tray","body":"A tray of brownies was cut into 16. Dax has eaten 12 of them. — with Suki and Dax.","art":"art/s-kitchen.webp","cta":"Read the story","level":4,"route":"#/stop/simplify-fractions"},"hook-simplify-fractions-hook":{"id":"hook-simplify-fractions-hook","kind":"hook","src":"stop:simplify-fractions#hook","title":"Can you? — Simplest form","body":"12/16 — is there a simpler name for the same share?","cta":"Find out how","level":4,"route":"#/stop/simplify-fractions"},"worked-simplify-fractions-worked0":{"id":"worked-simplify-fractions-worked0","kind":"worked","src":"stop:simplify-fractions#worked0","title":"Worked out — Simplest form","body":"Simplify 12/16: The biggest number that divides 12 and 16 → 4 · 12 ÷ 4 → 3 · 16 ÷ 4 → 4 · The simplest form → 3/4","cta":"Watch it step by step","level":4,"route":"#/stop/simplify-fractions"},"why-simplify-fractions-why1":{"id":"why-simplify-fractions-why1","kind":"why","src":"stop:simplify-fractions#why1","title":"Why “Simplest form” works","body":"Dividing the top and the bottom by the SAME number keeps the share the same, for the same reason multiplying does. You can do it in small steps (12/16 → 6/8 → 3/4), halving each time.","cta":"See why","level":4,"route":"#/stop/simplify-fractions"},"why-simplify-fractions-why2":{"id":"why-simplify-fractions-why2","kind":"why","src":"stop:simplify-fractions#why2","title":"Why “Simplest form” works","body":"Or in one step, with the biggest number that goes into both — here 4. When nothing but 1 divides both numbers, the fraction is in its simplest form: the biggest pieces that share can be cut into.","cta":"See why","level":4,"route":"#/stop/simplify-fractions"},"algebra-simplify-fractions-alg":{"id":"algebra-simplify-fractions-alg","kind":"algebra","src":"stop:simplify-fractions#alg","title":"The algebra behind “Simplest form”","body":"a/b = (a ÷ g)/(b ÷ g), g = the highest common factor of a and b","cta":"See why","level":4,"route":"#/stop/simplify-fractions"},"moment-simplify-fractions-beat2":{"id":"moment-simplify-fractions-beat2","kind":"moment","src":"story:simplify-fractions#beat2","badge":{"id":"story","label":"A story"},"title":"The brownie tray — on the notepad","body":"Suki: Glue the pieces back together. What is the biggest number that goes into 12 and 16? 16 ÷ 4 = 4","cta":"Read the story","level":4,"route":"#/stop/simplify-fractions"},"moral-simplify-fractions-beat5":{"id":"moral-simplify-fractions-beat5","kind":"moral","src":"story:simplify-fractions#beat5","badge":{"id":"story","label":"A story"},"title":"Dax, in “The brownie tray”","body":"Three quarters of a tray. That sounds even worse.","cta":"Read the story","level":4,"route":"#/stop/simplify-fractions"},"try-simplify-fractions-L4":{"id":"try-simplify-fractions-L4","kind":"try","level":4,"src":"try:simplify-fractions@4/1#0","title":"Simplest form — your turn","route":"#/stop/simplify-fractions","cta":"Practise this stop","play":{"q":"Simplify 2/10 = ?","opts":["1/5","2","1"],"after":"Find the biggest number that divides the top and the bottom, and divide both by it."}},"trick-mixed-numbers-idea":{"id":"trick-mixed-numbers-idea","kind":"trick","src":"stop:mixed-numbers#idea","title":"Mixed numbers and top-heavy fractions","body":"Each whole is as many pieces as the bottom number. Multiply, then add the extra pieces. A whole pie cut into quarters is 4 quarters. So 2 whole pies are 2 × 4 = 8 quarters, and 3 more quarters make 11 quarters: 2 3/4 = 11/4.","cta":"Learn the trick","level":4,"route":"#/stop/mixed-numbers"},"story-mixed-numbers-open":{"id":"story-mixed-numbers-open","kind":"story","src":"story:mixed-numbers#open","badge":{"id":"story","label":"A story"},"title":"Pies in quarters","body":"The bakery sells pie by the quarter. There are 2 whole pies and 3 extra quarters on the shelf. — with Rafi and Pip.","art":"art/s-bakery.webp","cta":"Read the story","level":4,"route":"#/stop/mixed-numbers"},"idea-mixed-numbers-case0":{"id":"idea-mixed-numbers-case0","kind":"idea","src":"stop:mixed-numbers#case0","title":"Mixed numbers and top-heavy fractions: Mixed to top-heavy","body":"Every whole is as many pieces as the bottom number. Multiply, then add the extra pieces.","cta":"See it worked","level":4,"route":"#/stop/mixed-numbers"},"idea-mixed-numbers-case1":{"id":"idea-mixed-numbers-case1","kind":"idea","src":"stop:mixed-numbers#case1","title":"Mixed numbers and top-heavy fractions: How many wholes?","body":"Going back: how many whole groups of the bottom number fit into the top? That is the whole number.","cta":"See it worked","level":4,"route":"#/stop/mixed-numbers"},"idea-mixed-numbers-case2":{"id":"idea-mixed-numbers-case2","kind":"idea","src":"stop:mixed-numbers#case2","title":"Mixed numbers and top-heavy fractions: Pieces left over","body":"Take away the pieces the wholes used up. What remains is the leftover fraction — always fewer than the bottom.","cta":"See it worked","level":4,"route":"#/stop/mixed-numbers"},"why-mixed-numbers-why1":{"id":"why-mixed-numbers-why1","kind":"why","src":"stop:mixed-numbers#why1","title":"Why “Mixed numbers and top-heavy fractions” works","body":"Going back, 11/4 asks: how many whole pies can I build from 11 quarters? Every 4 quarters make one pie, so 11 quarters make 2 pies with 3 quarters left over: 2 3/4.","cta":"See why","level":4,"route":"#/stop/mixed-numbers"},"algebra-mixed-numbers-alg":{"id":"algebra-mixed-numbers-alg","kind":"algebra","src":"stop:mixed-numbers#alg","title":"The algebra behind “Mixed numbers and top-heavy fractions”","body":"w a/b = (w × b + a)/b","cta":"See why","level":4,"route":"#/stop/mixed-numbers"},"moral-mixed-numbers-beat5":{"id":"moral-mixed-numbers-beat5","kind":"moral","src":"story:mixed-numbers#beat5","badge":{"id":"story","label":"A story"},"title":"Rafi, in “Pies in quarters”","body":"Two names for the same pile of pie.","cta":"Read the story","level":4,"route":"#/stop/mixed-numbers"},"try-mixed-numbers-L4":{"id":"try-mixed-numbers-L4","kind":"try","level":4,"src":"try:mixed-numbers@4/1#0","title":"Mixed numbers and top-heavy fractions — your turn","route":"#/stop/mixed-numbers","cta":"Practise this stop","play":{"q":"Write 2 1/4 as an improper fraction = ?","opts":["9/4","8","9"],"after":"Each whole is as many pieces as the bottom number. Multiply, then add the extra pieces."}},"worked-money-left-worked0":{"id":"worked-money-left-worked0","kind":"worked","src":"stop:money-left#worked0","title":"Worked out — What is left?","body":"Nova has 40 coins to spend at the fair and spends 12 on a ride and 9 on a snack. How many coins are left?: Everything spent: 12 + 9 → 21 · Left: 40 − 21 → 19","cta":"Watch it step by step","level":4,"route":"#/stop/money-left"},"algebra-money-left-alg":{"id":"algebra-money-left-alg","kind":"algebra","src":"stop:money-left#alg","title":"The algebra behind “What is left?”","body":"left = start − (spend₁ + spend₂ + …)","cta":"See why","level":4,"route":"#/stop/money-left"},"try-money-left-L4":{"id":"try-money-left-L4","kind":"try","level":4,"src":"try:money-left@4/3#0","title":"What is left? — your turn","route":"#/stop/money-left","cta":"Practise this stop","play":{"q":"Nova has 130 coins to spend at the fair and spends 14 on a ride, 20 on a snack and 10 on a badge. How many coins are left?","opts":["86","44","87"],"after":"Add up everything spent first, then take it away just once."}},"trick-saving-goal-idea":{"id":"trick-saving-goal-idea","kind":"trick","src":"stop:saving-goal#idea","title":"Saving for something","body":"Divide what is still needed by the saving each week — and if anything is left over, round UP. Each week adds the same amount, so the weeks are \"how many 6s fit into 50\". 6 × 8 = 48, so eight weeks is 48 coins.","cta":"Learn the trick","level":4,"route":"#/stop/saving-goal"},"story-saving-goal-open":{"id":"story-saving-goal-open","kind":"story","src":"story:saving-goal#open","badge":{"id":"story","label":"A story"},"title":"The kite in the window","body":"In the market there is a red kite for 50 coins. Rafi decides to save 6 coins a week for it. — with Rafi and Theo.","art":"art/s-market.webp","cta":"Read the story","level":4,"route":"#/stop/saving-goal"},"hook-saving-goal-hook":{"id":"hook-saving-goal-hook","kind":"hook","src":"stop:saving-goal#hook","title":"Can you? — Saving for something","body":"A kite costs 50 coins. Rafi saves 6 coins a week. How many weeks until he can buy it?","cta":"Find out how","level":4,"route":"#/stop/saving-goal"},"idea-saving-goal-case0":{"id":"idea-saving-goal-case0","kind":"idea","src":"stop:saving-goal#case0","title":"Saving for something: It fits exactly","body":"The weekly saving goes into the price with nothing left over, so the division is the answer.","cta":"See it worked","level":4,"route":"#/stop/saving-goal"},"worked-saving-goal-worked0":{"id":"worked-saving-goal-worked0","kind":"worked","src":"stop:saving-goal#worked0","title":"Worked out — Saving for something: It fits exactly","body":"A book costs 40 coins. Mira saves 5 coins a week. How many weeks until there is enough?: How many 5s make 40? → 8","cta":"Watch it step by step","level":4,"route":"#/stop/saving-goal"},"idea-saving-goal-case1":{"id":"idea-saving-goal-case1","kind":"idea","src":"stop:saving-goal#case1","title":"Saving for something: Round up","body":"A bit is left over, and the shop will not take \"nearly enough\". Any remainder means one more whole week.","cta":"See it worked","level":4,"route":"#/stop/saving-goal"},"worked-saving-goal-worked1":{"id":"worked-saving-goal-worked1","kind":"worked","src":"stop:saving-goal#worked1","title":"Worked out — Saving for something: Round up","body":"A kite costs 50 coins. Rafi saves 6 coins a week. How many weeks until there is enough?: Whole 6s that fit in 50 (not enough yet) → 8 · A bit is left, so one more week → 9","cta":"Watch it step by step","level":4,"route":"#/stop/saving-goal"},"idea-saving-goal-case2":{"id":"idea-saving-goal-case2","kind":"idea","src":"stop:saving-goal#case2","title":"Saving for something: Some saved already","body":"Take what is already saved off the price first. Only the rest has to be saved week by week.","cta":"See it worked","level":4,"route":"#/stop/saving-goal"},"worked-saving-goal-worked2":{"id":"worked-saving-goal-worked2","kind":"worked","src":"stop:saving-goal#worked2","title":"Worked out — Saving for something: Some saved already","body":"A torch costs 60 coins. Theo has 15 coins already and saves 8 coins a week. How many weeks until there is enough?: Still to save: 60 − 15 → 45 · Whole 8s that fit in 45 (not enough yet) → 5 · A bit is left, so one more week → 6","cta":"Watch it step by step","level":4,"route":"#/stop/saving-goal"},"why-saving-goal-why1":{"id":"why-saving-goal-why1","kind":"why","src":"stop:saving-goal#why1","title":"Why “Saving for something” works","body":"But 48 is not 50. After eight weeks Rafi still cannot buy the kite — he is 2 coins short, and the shop will not take 48. He needs a ninth week, which takes him to 54. So the answer is 9, even though 50 ÷ 6 is only 8 and a bit.","cta":"See why","level":4,"route":"#/stop/saving-goal"},"why-saving-goal-why2":{"id":"why-saving-goal-why2","kind":"why","src":"stop:saving-goal#why2","title":"Why “Saving for something” works","body":"That is the rule for any goal: a part-week still has to be a whole week, so a remainder always means one more. And if some coins are saved already, take them off the price first — only the rest has to be saved.","cta":"See why","level":4,"route":"#/stop/saving-goal"},"algebra-saving-goal-alg":{"id":"algebra-saving-goal-alg","kind":"algebra","src":"stop:saving-goal#alg","title":"The algebra behind “Saving for something”","body":"weeks = ⌈(price − saved already) ÷ per week⌉","cta":"See why","level":4,"route":"#/stop/saving-goal"},"moment-saving-goal-beat3":{"id":"moment-saving-goal-beat3","kind":"moment","src":"story:saving-goal#beat3","badge":{"id":"story","label":"A story"},"title":"The kite in the window — on the notepad","body":"Rafi: No — I would be 2 short. 50 − 48 = 2","cta":"Read the story","level":4,"route":"#/stop/saving-goal"},"moral-saving-goal-beat5":{"id":"moral-saving-goal-beat5","kind":"moral","src":"story:saving-goal#beat5","badge":{"id":"story","label":"A story"},"title":"Rafi, in “The kite in the window”","body":"Nine weeks. When there is a bit left over, round UP.","cta":"Read the story","level":4,"route":"#/stop/saving-goal"},"try-saving-goal-L4":{"id":"try-saving-goal-L4","kind":"try","level":4,"src":"try:saving-goal@4/1#0","title":"Saving for something — your turn","route":"#/stop/saving-goal","cta":"Practise this stop","play":{"q":"A board game costs 18 coins. Nova saves 2 coins a week. How many weeks until there is enough?","opts":["9","10","8"],"after":"Divide what is still needed by the saving each week — and if anything is left over, round UP."}},"trick-kinds-of-triangle-idea":{"id":"trick-kinds-of-triangle-idea","kind":"trick","src":"stop:kinds-of-triangle#idea","title":"Kinds of triangle","body":"Count the equal sides: three equal is equilateral, two is isosceles, none is scalene. Or look at the biggest angle: 90° is right-angled. The names come from what is the same. Equilateral means \"equal sides\" — all three. Isosceles means \"equal legs\" — two sides match, and the two angles at the bottom of those sides match too, because the triangle is its own mirror image down the middle. Scalene means no two sides match.","cta":"Learn the trick","level":4,"route":"#/stop/kinds-of-triangle"},"story-kinds-of-triangle-open":{"id":"story-kinds-of-triangle-open","kind":"story","src":"story:kinds-of-triangle#open","badge":{"id":"story","label":"A story"},"title":"The garden frame","body":"Theo and Suki are building a bean frame from three canes: 5, 5 and 8 hands long. — with Theo and Suki.","art":"art/s-garden.webp","cta":"Read the story","level":4,"route":"#/stop/kinds-of-triangle"},"hook-kinds-of-triangle-hook":{"id":"hook-kinds-of-triangle-hook","kind":"hook","src":"stop:kinds-of-triangle#hook","title":"Can you? — Kinds of triangle","body":"Sides of 5, 5 and 8 — what kind of triangle is that?","cta":"Find out how","level":4,"route":"#/stop/kinds-of-triangle"},"idea-kinds-of-triangle-case0":{"id":"idea-kinds-of-triangle-case0","kind":"idea","src":"stop:kinds-of-triangle#case0","title":"Kinds of triangle: Equilateral","body":"All three sides are the same length — and so all three angles are the same too: 180° ÷ 3 = 60° each.","cta":"See it worked","level":4,"route":"#/stop/kinds-of-triangle"},"worked-kinds-of-triangle-worked0":{"id":"worked-kinds-of-triangle-worked0","kind":"worked","src":"stop:kinds-of-triangle#worked0","title":"Worked out — Kinds of triangle: Equilateral","body":"A triangle has sides of 6 cm, 6 cm and 6 cm. What kind of triangle is it?: How many sides share a length with another side? → 3 · So the triangle is → equilateral","cta":"Watch it step by step","level":4,"route":"#/stop/kinds-of-triangle"},"idea-kinds-of-triangle-case1":{"id":"idea-kinds-of-triangle-case1","kind":"idea","src":"stop:kinds-of-triangle#case1","title":"Kinds of triangle: Isosceles","body":"Exactly two sides match. The two angles at the ends of the odd side match as well, because the triangle is its own mirror image.","cta":"See it worked","level":4,"route":"#/stop/kinds-of-triangle"},"worked-kinds-of-triangle-worked1":{"id":"worked-kinds-of-triangle-worked1","kind":"worked","src":"stop:kinds-of-triangle#worked1","title":"Worked out — Kinds of triangle: Isosceles","body":"A triangle has sides of 5 cm, 5 cm and 8 cm. What kind of triangle is it?: How many sides share a length with another side? → 2 · So the triangle is → isosceles","cta":"Watch it step by step","level":4,"route":"#/stop/kinds-of-triangle"},"idea-kinds-of-triangle-case2":{"id":"idea-kinds-of-triangle-case2","kind":"idea","src":"stop:kinds-of-triangle#case2","title":"Kinds of triangle: Scalene","body":"No two sides match, so no two angles match either. Most triangles you draw without trying are scalene.","cta":"See it worked","level":4,"route":"#/stop/kinds-of-triangle"},"worked-kinds-of-triangle-worked2":{"id":"worked-kinds-of-triangle-worked2","kind":"worked","src":"stop:kinds-of-triangle#worked2","title":"Worked out — Kinds of triangle: Scalene","body":"A triangle has sides of 4 cm, 6 cm and 7 cm. What kind of triangle is it?: How many sides share a length with another side? → 0 · So the triangle is → scalene","cta":"Watch it step by step","level":4,"route":"#/stop/kinds-of-triangle"},"idea-kinds-of-triangle-case3":{"id":"idea-kinds-of-triangle-case3","kind":"idea","src":"stop:kinds-of-triangle#case3","title":"Kinds of triangle: Right-angled","body":"Now sort by the biggest angle instead. One angle is exactly 90° — a square corner.","cta":"See it worked","level":4,"route":"#/stop/kinds-of-triangle"},"worked-kinds-of-triangle-worked3":{"id":"worked-kinds-of-triangle-worked3","kind":"worked","src":"stop:kinds-of-triangle#worked3","title":"Worked out — Kinds of triangle: Right-angled","body":"A triangle has angles of 35° and 55°. What kind of triangle is it?: The third angle: 180 − 35 − 55 → 90 · The biggest of the three angles → 90 · So the triangle is → right-angled","cta":"Watch it step by step","level":4,"route":"#/stop/kinds-of-triangle"},"idea-kinds-of-triangle-case4":{"id":"idea-kinds-of-triangle-case4","kind":"idea","src":"stop:kinds-of-triangle#case4","title":"Kinds of triangle: Acute-angled","body":"Every angle is smaller than 90°. Find the third angle first — it is the one people forget to check.","cta":"See it worked","level":4,"route":"#/stop/kinds-of-triangle"},"worked-kinds-of-triangle-worked4":{"id":"worked-kinds-of-triangle-worked4","kind":"worked","src":"stop:kinds-of-triangle#worked4","title":"Worked out — Kinds of triangle: Acute-angled","body":"A triangle has angles of 50° and 60°. What kind of triangle is it?: The third angle: 180 − 50 − 60 → 70 · The biggest of the three angles → 70 · So the triangle is → acute-angled","cta":"Watch it step by step","level":4,"route":"#/stop/kinds-of-triangle"},"idea-kinds-of-triangle-case5":{"id":"idea-kinds-of-triangle-case5","kind":"idea","src":"stop:kinds-of-triangle#case5","title":"Kinds of triangle: Obtuse-angled","body":"One angle is bigger than 90°. There can only ever be one, because the three angles share just 180°.","cta":"See it worked","level":4,"route":"#/stop/kinds-of-triangle"},"worked-kinds-of-triangle-worked5":{"id":"worked-kinds-of-triangle-worked5","kind":"worked","src":"stop:kinds-of-triangle#worked5","title":"Worked out — Kinds of triangle: Obtuse-angled","body":"A triangle has angles of 25° and 35°. What kind of triangle is it?: The third angle: 180 − 25 − 35 → 120 · The biggest of the three angles → 120 · So the triangle is → obtuse-angled","cta":"Watch it step by step","level":4,"route":"#/stop/kinds-of-triangle"},"why-kinds-of-triangle-why1":{"id":"why-kinds-of-triangle-why1","kind":"why","src":"stop:kinds-of-triangle#why1","title":"Why “Kinds of triangle” works","body":"You can also sort triangles by their biggest angle. The three angles always add up to 180°, so only one of them can be 90° or more. If the biggest is exactly 90°, it is right-angled; bigger than 90°, obtuse-angled; if all three are smaller, acute-angled.","cta":"See why","level":4,"route":"#/stop/kinds-of-triangle"},"why-kinds-of-triangle-why2":{"id":"why-kinds-of-triangle-why2","kind":"why","src":"stop:kinds-of-triangle#why2","title":"Why “Kinds of triangle” works","body":"That is why you only need to find the biggest angle: once you know two angles, the third is 180° take away the other two.","cta":"See why","level":4,"route":"#/stop/kinds-of-triangle"},"algebra-kinds-of-triangle-alg":{"id":"algebra-kinds-of-triangle-alg","kind":"algebra","src":"stop:kinds-of-triangle#alg","title":"The algebra behind “Kinds of triangle”","body":"a = b = c → equilateral; exactly two equal → isosceles; none equal → scalene","cta":"See why","level":4,"route":"#/stop/kinds-of-triangle"},"moment-kinds-of-triangle-beat4":{"id":"moment-kinds-of-triangle-beat4","kind":"moment","src":"story:kinds-of-triangle#beat4","badge":{"id":"story","label":"A story"},"title":"The garden frame — on the notepad","body":"Suki: If all three canes were 5, it would be equilateral. If none matched, scalene. 5 × 3 = 15","cta":"Read the story","level":4,"route":"#/stop/kinds-of-triangle"},"moral-kinds-of-triangle-beat5":{"id":"moral-kinds-of-triangle-beat5","kind":"moral","src":"story:kinds-of-triangle#beat5","badge":{"id":"story","label":"A story"},"title":"Theo, in “The garden frame”","body":"Two equal canes, one long one. Isosceles it is.","cta":"Read the story","level":4,"route":"#/stop/kinds-of-triangle"},"try-kinds-of-triangle-L4":{"id":"try-kinds-of-triangle-L4","kind":"try","level":4,"src":"try:kinds-of-triangle@4/1#0","title":"Kinds of triangle — your turn","route":"#/stop/kinds-of-triangle","cta":"Practise this stop","play":{"q":"A triangle has sides of 9 cm, 12 cm and 11 cm. What kind of triangle is it?","opts":["scalene","equilateral","isosceles"],"after":"Count the equal sides: three equal is equilateral, two is isosceles, none is scalene. Or look at the biggest angle: 90° is right-angled."}},"trick-four-sided-shapes-idea":{"id":"trick-four-sided-shapes-idea","kind":"trick","src":"stop:four-sided-shapes#idea","title":"Four-sided shapes","body":"Ask three questions — how many pairs of parallel sides, are all sides equal, are there right angles — and the answers name the shape. Every four-sided shape is a quadrilateral, and the family is sorted by what it keeps. Two pairs of parallel sides make a parallelogram: slide the top edge along and it stays the same length and direction as the bottom.","cta":"Learn the trick","level":4,"route":"#/stop/four-sided-shapes"},"story-four-sided-shapes-open":{"id":"story-four-sided-shapes-open","kind":"story","src":"story:four-sided-shapes#open","badge":{"id":"story","label":"A story"},"title":"The tile shop","body":"In a tile shop, Ines picks up a tile with four equal sides. It is leaning over like a pushed square. — with Mira and Ines.","art":"art/s-shop.webp","cta":"Read the story","level":4,"route":"#/stop/four-sided-shapes"},"hook-four-sided-shapes-hook":{"id":"hook-four-sided-shapes-hook","kind":"hook","src":"stop:four-sided-shapes#hook","title":"Can you? — Four-sided shapes","body":"A square and a rhombus both have four equal sides. So what is the difference?","cta":"Find out how","level":4,"route":"#/stop/four-sided-shapes"},"idea-four-sided-shapes-case0":{"id":"idea-four-sided-shapes-case0","kind":"idea","src":"stop:four-sided-shapes#case0","title":"Four-sided shapes: Square","body":"Every rule at once: two pairs of parallel sides, all four sides equal, and every corner a right angle.","cta":"See it worked","level":4,"route":"#/stop/four-sided-shapes"},"worked-four-sided-shapes-worked0":{"id":"worked-four-sided-shapes-worked0","kind":"worked","src":"stop:four-sided-shapes#worked0","title":"Worked out — Four-sided shapes: Square","body":"All four sides are the same length, and every corner is a right angle. Which shape is it?: How many pairs of parallel sides? → 2 · Are all four sides the same length? → Yes · Are the corners right angles? → Yes · So it is a… → square","cta":"Watch it step by step","level":4,"route":"#/stop/four-sided-shapes"},"idea-four-sided-shapes-case1":{"id":"idea-four-sided-shapes-case1","kind":"idea","src":"stop:four-sided-shapes#case1","title":"Four-sided shapes: Rectangle","body":"Right angles, but the sides are not all the same — two long, two short. A square is a rectangle whose sides happen to match.","cta":"See it worked","level":4,"route":"#/stop/four-sided-shapes"},"worked-four-sided-shapes-worked1":{"id":"worked-four-sided-shapes-worked1","kind":"worked","src":"stop:four-sided-shapes#worked1","title":"Worked out — Four-sided shapes: Rectangle","body":"Every corner is a right angle, and opposite sides are equal — but the sides are not all the same length. Which shape is it?: How many pairs of parallel sides? → 2 · Are all four sides the same length? → No · Are the corners right angles? → Yes · So it is a… → rectangle","cta":"Watch it step by step","level":4,"route":"#/stop/four-sided-shapes"},"idea-four-sided-shapes-case2":{"id":"idea-four-sided-shapes-case2","kind":"idea","src":"stop:four-sided-shapes#case2","title":"Four-sided shapes: Rhombus","body":"All four sides equal, like a square — but pushed over, so no corner is a right angle.","cta":"See it worked","level":4,"route":"#/stop/four-sided-shapes"},"worked-four-sided-shapes-worked2":{"id":"worked-four-sided-shapes-worked2","kind":"worked","src":"stop:four-sided-shapes#worked2","title":"Worked out — Four-sided shapes: Rhombus","body":"All four sides are the same length, but none of its corners is a right angle. Which shape is it?: How many pairs of parallel sides? → 2 · Are all four sides the same length? → Yes · Are the corners right angles? → No · So it is a… → rhombus","cta":"Watch it step by step","level":4,"route":"#/stop/four-sided-shapes"},"idea-four-sided-shapes-case3":{"id":"idea-four-sided-shapes-case3","kind":"idea","src":"stop:four-sided-shapes#case3","title":"Four-sided shapes: Parallelogram","body":"Two pairs of parallel sides and nothing more: no right angles, and the sides are not all equal. A rectangle pushed over.","cta":"See it worked","level":4,"route":"#/stop/four-sided-shapes"},"worked-four-sided-shapes-worked3":{"id":"worked-four-sided-shapes-worked3","kind":"worked","src":"stop:four-sided-shapes#worked3","title":"Worked out — Four-sided shapes: Parallelogram","body":"Two pairs of parallel sides, opposite sides equal, no right angles, and not all sides the same. Which shape is it?: How many pairs of parallel sides? → 2 · Are all four sides the same length? → No · Are the corners right angles? → No · So it is a… → parallelogram","cta":"Watch it step by step","level":4,"route":"#/stop/four-sided-shapes"},"idea-four-sided-shapes-case4":{"id":"idea-four-sided-shapes-case4","kind":"idea","src":"stop:four-sided-shapes#case4","title":"Four-sided shapes: Trapezium","body":"Only ONE pair of parallel sides. That single missing pair is what stops it being a parallelogram.","cta":"See it worked","level":4,"route":"#/stop/four-sided-shapes"},"worked-four-sided-shapes-worked4":{"id":"worked-four-sided-shapes-worked4","kind":"worked","src":"stop:four-sided-shapes#worked4","title":"Worked out — Four-sided shapes: Trapezium","body":"It has exactly one pair of parallel sides. Which shape is it?: How many pairs of parallel sides? → 1 · Are all four sides the same length? → No · Are the corners right angles? → No · So it is a… → trapezium","cta":"Watch it step by step","level":4,"route":"#/stop/four-sided-shapes"},"idea-four-sided-shapes-case5":{"id":"idea-four-sided-shapes-case5","kind":"idea","src":"stop:four-sided-shapes#case5","title":"Four-sided shapes: Kite","body":"No parallel sides at all. The equal sides come in pairs that sit next to each other, not opposite.","cta":"See it worked","level":4,"route":"#/stop/four-sided-shapes"},"worked-four-sided-shapes-worked5":{"id":"worked-four-sided-shapes-worked5","kind":"worked","src":"stop:four-sided-shapes#worked5","title":"Worked out — Four-sided shapes: Kite","body":"Two pairs of equal sides that sit next to each other, and no parallel sides at all. Which shape is it?: How many pairs of parallel sides? → 0 · Are all four sides the same length? → No · Are the corners right angles? → No · So it is a… → kite","cta":"Watch it step by step","level":4,"route":"#/stop/four-sided-shapes"},"why-four-sided-shapes-why1":{"id":"why-four-sided-shapes-why1","kind":"why","src":"stop:four-sided-shapes#why1","title":"Why “Four-sided shapes” works","body":"Then add rules. A parallelogram with right angles is a rectangle. A parallelogram with all four sides equal is a rhombus. Both rules at once — equal sides AND right angles — is a square. That is why a square is a special rectangle and a special rhombus at the same time.","cta":"See why","level":4,"route":"#/stop/four-sided-shapes"},"why-four-sided-shapes-why2":{"id":"why-four-sided-shapes-why2","kind":"why","src":"stop:four-sided-shapes#why2","title":"Why “Four-sided shapes” works","body":"With only one pair of parallel sides it is a trapezium. With no parallel sides but two pairs of equal sides next to each other, it is a kite — fold it down the middle and the halves match.","cta":"See why","level":4,"route":"#/stop/four-sided-shapes"},"algebra-four-sided-shapes-alg":{"id":"algebra-four-sided-shapes-alg","kind":"algebra","src":"stop:four-sided-shapes#alg","title":"The algebra behind “Four-sided shapes”","body":"parallelogram + right angles = rectangle; + equal sides = rhombus; + both = square","cta":"See why","level":4,"route":"#/stop/four-sided-shapes"},"moment-four-sided-shapes-beat3":{"id":"moment-four-sided-shapes-beat3","kind":"moment","src":"story:four-sided-shapes#beat3","badge":{"id":"story","label":"A story"},"title":"The tile shop — on the notepad","body":"Ines: No — two are pointy and two are wide. Their sizes still add to a full turn. 60 + 120 + 60 + 120 = 360","cta":"Read the story","level":4,"route":"#/stop/four-sided-shapes"},"moral-four-sided-shapes-beat5":{"id":"moral-four-sided-shapes-beat5","kind":"moral","src":"story:four-sided-shapes#beat5","badge":{"id":"story","label":"A story"},"title":"Ines, in “The tile shop”","body":"And two pairs of parallel sides, like every parallelogram.","cta":"Read the story","level":4,"route":"#/stop/four-sided-shapes"},"try-four-sided-shapes-L4":{"id":"try-four-sided-shapes-L4","kind":"try","level":4,"src":"try:four-sided-shapes@4/1#0","title":"Four-sided shapes — your turn","route":"#/stop/four-sided-shapes","cta":"Practise this stop","play":{"q":"It has exactly one pair of parallel sides. Which shape is it?","opts":["trapezium","square","rectangle"],"after":"Ask three questions — how many pairs of parallel sides, are all sides equal, are there right angles — and the answers name the shape."}},"trick-coordinates-and-moves-idea":{"id":"trick-coordinates-and-moves-idea","kind":"trick","src":"stop:coordinates-and-moves#idea","title":"Coordinates and moves","body":"A point is (across, up): x first, then y. Moving right or left changes only x; up or down changes only y. A coordinate is two instructions from the corner marked 0. The first number says how far across the bottom to walk; the second says how far to climb. Everyone agrees on the order — \"along the corridor, then up the stairs\" — so a point has exactly one address.","cta":"Learn the trick","level":4,"route":"#/stop/coordinates-and-moves"},"story-coordinates-and-moves-open":{"id":"story-coordinates-and-moves-open","kind":"story","src":"story:coordinates-and-moves#open","badge":{"id":"story","label":"A story"},"title":"The treasure grid","body":"On the beach, Nova draws a grid in the sand. The shell is buried at (3, 2). — with Dax and Nova.","art":"art/s-beach.webp","cta":"Read the story","level":4,"route":"#/stop/coordinates-and-moves"},"hook-coordinates-and-moves-hook":{"id":"hook-coordinates-and-moves-hook","kind":"hook","src":"stop:coordinates-and-moves#hook","title":"Can you? — Coordinates and moves","body":"A treasure map says (3, 5). Do you go across first, or up?","cta":"Find out how","level":4,"route":"#/stop/coordinates-and-moves"},"idea-coordinates-and-moves-case0":{"id":"idea-coordinates-and-moves-case0","kind":"idea","src":"stop:coordinates-and-moves#case0","title":"Coordinates and moves: Read the across number","body":"The x-coordinate is always the FIRST number: how far you walk along the bottom before you climb.","cta":"See it worked","level":4,"route":"#/stop/coordinates-and-moves"},"worked-coordinates-and-moves-worked0":{"id":"worked-coordinates-and-moves-worked0","kind":"worked","src":"stop:coordinates-and-moves#worked0","title":"Worked out — Coordinates and moves: Read the across number","body":"What is the x-coordinate of point A?: Across the bottom first: how many squares to get under A? → 4 · The x-coordinate is the across number → 4","cta":"Watch it step by step","level":4,"route":"#/stop/coordinates-and-moves"},"idea-coordinates-and-moves-case1":{"id":"idea-coordinates-and-moves-case1","kind":"idea","src":"stop:coordinates-and-moves#case1","title":"Coordinates and moves: Read the up number","body":"The y-coordinate is the SECOND number: how far you climb once you are under the point.","cta":"See it worked","level":4,"route":"#/stop/coordinates-and-moves"},"worked-coordinates-and-moves-worked1":{"id":"worked-coordinates-and-moves-worked1","kind":"worked","src":"stop:coordinates-and-moves#worked1","title":"Worked out — Coordinates and moves: Read the up number","body":"What is the y-coordinate of point A?: Across the bottom first: how many squares to get under A? → 6 · Then up: how many squares to reach A? → 3","cta":"Watch it step by step","level":4,"route":"#/stop/coordinates-and-moves"},"idea-coordinates-and-moves-case2":{"id":"idea-coordinates-and-moves-case2","kind":"idea","src":"stop:coordinates-and-moves#case2","title":"Coordinates and moves: Move right or up: add","body":"Moving right makes the across number bigger, so add. Moving up would add to the up number instead.","cta":"See it worked","level":4,"route":"#/stop/coordinates-and-moves"},"worked-coordinates-and-moves-worked2":{"id":"worked-coordinates-and-moves-worked2","kind":"worked","src":"stop:coordinates-and-moves#worked2","title":"Worked out — Coordinates and moves: Move right or up: add","body":"Point A moves 4 right and 1 up. What is its new x-coordinate?: A starts with x = → 3 · Add 4 → 7","cta":"Watch it step by step","level":4,"route":"#/stop/coordinates-and-moves"},"idea-coordinates-and-moves-case3":{"id":"idea-coordinates-and-moves-case3","kind":"idea","src":"stop:coordinates-and-moves#case3","title":"Coordinates and moves: Move left or down: take away","body":"Moving left or down goes back towards 0, so take away.","cta":"See it worked","level":4,"route":"#/stop/coordinates-and-moves"},"worked-coordinates-and-moves-worked3":{"id":"worked-coordinates-and-moves-worked3","kind":"worked","src":"stop:coordinates-and-moves#worked3","title":"Worked out — Coordinates and moves: Move left or down: take away","body":"Point A moves 3 left and 2 up. What is its new x-coordinate?: A starts with x = → 7 · Take away 3 → 4","cta":"Watch it step by step","level":4,"route":"#/stop/coordinates-and-moves"},"idea-coordinates-and-moves-case4":{"id":"idea-coordinates-and-moves-case4","kind":"idea","src":"stop:coordinates-and-moves#case4","title":"Coordinates and moves: A move that leaves it alone","body":"Moving only up or down never changes the across number — walking up stairs does not move you sideways.","cta":"See it worked","level":4,"route":"#/stop/coordinates-and-moves"},"worked-coordinates-and-moves-worked4":{"id":"worked-coordinates-and-moves-worked4","kind":"worked","src":"stop:coordinates-and-moves#worked4","title":"Worked out — Coordinates and moves: A move that leaves it alone","body":"Point A moves 5 up. What is its new x-coordinate?: A starts with x = → 4 · It does not move sideways, so x stays → 4","cta":"Watch it step by step","level":4,"route":"#/stop/coordinates-and-moves"},"idea-coordinates-and-moves-case5":{"id":"idea-coordinates-and-moves-case5","kind":"idea","src":"stop:coordinates-and-moves#case5","title":"Coordinates and moves: How far it moved","body":"Working backwards: the gap between the two across numbers is how far it slid sideways (or the up numbers, for up and down).","cta":"See it worked","level":4,"route":"#/stop/coordinates-and-moves"},"worked-coordinates-and-moves-worked5":{"id":"worked-coordinates-and-moves-worked5","kind":"worked","src":"stop:coordinates-and-moves#worked5","title":"Worked out — Coordinates and moves: How far it moved","body":"Point A slides to point B. How many squares right did it move?: The x-coordinate of B → 7 · The x-coordinate of A → 2 · The gap between them → 5","cta":"Watch it step by step","level":4,"route":"#/stop/coordinates-and-moves"},"why-coordinates-and-moves-why1":{"id":"why-coordinates-and-moves-why1","kind":"why","src":"stop:coordinates-and-moves#why1","title":"Why “Coordinates and moves” works","body":"Moving a point without turning it (a translation) is also two instructions. Going 3 to the right adds 3 to the across number and leaves the up number alone, because walking sideways does not make you any higher.","cta":"See why","level":4,"route":"#/stop/coordinates-and-moves"},"why-coordinates-and-moves-why2":{"id":"why-coordinates-and-moves-why2","kind":"why","src":"stop:coordinates-and-moves#why2","title":"Why “Coordinates and moves” works","body":"So you can work out where a point lands without drawing it: add for right and up, take away for left and down. Going backwards, the gap between the across numbers is how far it moved sideways.","cta":"See why","level":4,"route":"#/stop/coordinates-and-moves"},"algebra-coordinates-and-moves-alg":{"id":"algebra-coordinates-and-moves-alg","kind":"algebra","src":"stop:coordinates-and-moves#alg","title":"The algebra behind “Coordinates and moves”","body":"(x, y) moved a right and b up → (x + a, y + b)","cta":"See why","level":4,"route":"#/stop/coordinates-and-moves"},"moment-coordinates-and-moves-beat5":{"id":"moment-coordinates-and-moves-beat5","kind":"moment","src":"story:coordinates-and-moves#beat5","badge":{"id":"story","label":"A story"},"title":"The treasure grid — on the notepad","body":"Nova: And up changes only the up number. 2 + 1 = 3","cta":"Read the story","level":4,"route":"#/stop/coordinates-and-moves"},"moral-coordinates-and-moves-beat6":{"id":"moral-coordinates-and-moves-beat6","kind":"moral","src":"story:coordinates-and-moves#beat6","badge":{"id":"story","label":"A story"},"title":"Dax, in “The treasure grid”","body":"Dig at (7, 3)! The across number is 7.","cta":"Read the story","level":4,"route":"#/stop/coordinates-and-moves"},"try-coordinates-and-moves-L4":{"id":"try-coordinates-and-moves-L4","kind":"try","level":4,"src":"try:coordinates-and-moves@4/1#0","title":"Coordinates and moves — your turn","route":"#/stop/coordinates-and-moves","cta":"Practise this stop","play":{"q":"What is the x-coordinate of point A?","opts":["1","2","0"],"after":"A point is (across, up): x first, then y. Moving right or left changes only x; up or down changes only y."}},"trick-times-25-idea":{"id":"trick-times-25-idea","kind":"trick","src":"stop:times-25#idea","title":"Times 25 is a quarter of 100","body":"Divide by 4, then times by 100. Four 25s make 100, like four quarters make a dollar.","cta":"Learn the trick","level":4,"route":"#/stop/times-25"},"story-times-25-open":{"id":"story-times-25-open","kind":"story","src":"story:times-25#open","badge":{"id":"story","label":"A story"},"title":"The ride tokens","body":"Every ride at the fair costs 25 tokens. Ines’s class went on 36 rides. — with Ines and Dax.","art":"art/s-fair.webp","cta":"Read the story","level":4,"route":"#/stop/times-25"},"hook-times-25-hook":{"id":"hook-times-25-hook","kind":"hook","src":"stop:times-25#hook","title":"Can you? — Times 25 is a quarter of 100","body":"36 × 25 — think money.","cta":"Find out how","level":4,"route":"#/stop/times-25"},"worked-times-25-worked0":{"id":"worked-times-25-worked0","kind":"worked","src":"stop:times-25#worked0","title":"Worked out — Times 25 is a quarter of 100","body":"36 × 25: 36 ÷ 4 → 9 · × 100 → 900","cta":"Watch it step by step","level":4,"route":"#/stop/times-25"},"why-times-25-why1":{"id":"why-times-25-why1","kind":"why","src":"stop:times-25#why1","title":"Why “Times 25 is a quarter of 100” works","body":"So 36 lots of 25 is 36 quarters — 9 whole hundreds.","cta":"See why","level":4,"route":"#/stop/times-25"},"algebra-times-25-alg":{"id":"algebra-times-25-alg","kind":"algebra","src":"stop:times-25#alg","title":"The algebra behind “Times 25 is a quarter of 100”","body":"n × 25 = (n ÷ 4) × 100","cta":"See why","level":4,"route":"#/stop/times-25"},"moment-times-25-beat3":{"id":"moment-times-25-beat3","kind":"moment","src":"story:times-25#beat3","badge":{"id":"story","label":"A story"},"title":"The ride tokens — on the notepad","body":"Ines: Each four rides is a hundred tokens. 9 × 100 = 900","cta":"Read the story","level":4,"route":"#/stop/times-25"},"moral-times-25-beat4":{"id":"moral-times-25-beat4","kind":"moral","src":"story:times-25#beat4","badge":{"id":"story","label":"A story"},"title":"Dax, in “The ride tokens”","body":"Nine hundred tokens!","cta":"Read the story","level":4,"route":"#/stop/times-25"},"try-times-25-L4":{"id":"try-times-25-L4","kind":"try","level":4,"src":"try:times-25@4/1#0","title":"Times 25 is a quarter of 100 — your turn","route":"#/stop/times-25","cta":"Practise this stop","play":{"q":"36 × 25 = ?","opts":["900","9","901"],"after":"Divide by 4, then times by 100."}},"trick-halve-double-idea":{"id":"trick-halve-double-idea","kind":"trick","src":"stop:halve-double#idea","title":"Halve one, double the other","body":"Halve one number and double the other. The answer does not change — but the sum gets easier. Picture a rectangle 16 wide and 35 tall. Cut it in half down the middle and stack the halves: now it is 8 wide and 70 tall. Same area.","cta":"Learn the trick","level":4,"route":"#/stop/halve-double"},"story-halve-double-open":{"id":"story-halve-double-open","kind":"story","src":"story:halve-double#open","badge":{"id":"story","label":"A story"},"title":"The tiled floor","body":"A new floor: 16 rows of tiles, with 35 tiles in each row. — with Suki and Theo.","art":"art/s-room.webp","cta":"Read the story","level":4,"route":"#/stop/halve-double"},"hook-halve-double-hook":{"id":"hook-halve-double-hook","kind":"hook","src":"stop:halve-double#hook","title":"Can you? — Halve one, double the other","body":"16 × 35 — neither number is friendly.","cta":"Find out how","level":4,"route":"#/stop/halve-double"},"worked-halve-double-worked0":{"id":"worked-halve-double-worked0","kind":"worked","src":"stop:halve-double#worked0","title":"Worked out — Halve one, double the other","body":"16 × 35: Halve 16 → 8 · Double 35 → 70 · 8 × 70 → 560","cta":"Watch it step by step","level":4,"route":"#/stop/halve-double"},"why-halve-double-why1":{"id":"why-halve-double-why1","kind":"why","src":"stop:halve-double#why1","title":"Why “Halve one, double the other” works","body":"Keep going until one number is easy: 16 × 35 = 8 × 70 = 560.","cta":"See why","level":4,"route":"#/stop/halve-double"},"algebra-halve-double-alg":{"id":"algebra-halve-double-alg","kind":"algebra","src":"stop:halve-double#alg","title":"The algebra behind “Halve one, double the other”","body":"a × b = (a ÷ 2) × (b × 2)","cta":"See why","level":4,"route":"#/stop/halve-double"},"moment-halve-double-beat3":{"id":"moment-halve-double-beat3","kind":"moment","src":"story:halve-double#beat3","badge":{"id":"story","label":"A story"},"title":"The tiled floor — on the notepad","body":"Suki: …each twice as long. 35 × 2 = 70","cta":"Read the story","level":4,"route":"#/stop/halve-double"},"moral-halve-double-beat5":{"id":"moral-halve-double-beat5","kind":"moral","src":"story:halve-double#beat5","badge":{"id":"story","label":"A story"},"title":"Suki, in “The tiled floor”","body":"Same tiles, same floor. Just rearranged.","cta":"Read the story","level":4,"route":"#/stop/halve-double"},"try-halve-double-L4":{"id":"try-halve-double-L4","kind":"try","level":4,"src":"try:halve-double@4/1#0","title":"Halve one, double the other — your turn","route":"#/stop/halve-double","cta":"Practise this stop","play":{"q":"14 × 35 = ?","opts":["490","7","70"],"after":"Halve one number and double the other. The answer does not change — but the sum gets easier."}},"trick-factor-pairs-idea":{"id":"trick-factor-pairs-idea","kind":"trick","src":"stop:factor-pairs#idea","title":"Factors come in pairs","body":"Find factors in pairs: test 1, 2, 3… and every one that divides gives you its partner too. Stop when the number times itself passes the target. A factor of 36 is a number that divides it exactly. Every time one does, it comes with a partner: 36 ÷ 4 = 9, so 4 × 9 = 36, and 9 is a factor as well. Draw 36 dots in 4 rows and there are 9 in each row — one rectangle, two factors.","cta":"Learn the trick","level":4,"route":"#/stop/factor-pairs"},"story-factor-pairs-open":{"id":"story-factor-pairs-open","kind":"story","src":"story:factor-pairs#open","badge":{"id":"story","label":"A story"},"title":"Planting the orchard","body":"The forest club has 36 saplings to plant in a neat rectangle. How many different rectangles could they make? — with Mira and Pip.","art":"art/s-forest.webp","cta":"Read the story","level":4,"route":"#/stop/factor-pairs"},"hook-factor-pairs-hook":{"id":"hook-factor-pairs-hook","kind":"hook","src":"stop:factor-pairs#hook","title":"Can you? — Factors come in pairs","body":"How many numbers divide 36 exactly? Can you be sure you found them all?","cta":"Find out how","level":4,"route":"#/stop/factor-pairs"},"idea-factor-pairs-case0":{"id":"idea-factor-pairs-case0","kind":"idea","src":"stop:factor-pairs#case0","title":"Factors come in pairs: Every factor has a partner","body":"Each number that divides gives you two factors — itself and its partner — so the count comes out even.","cta":"See it worked","level":4,"route":"#/stop/factor-pairs"},"worked-factor-pairs-worked0":{"id":"worked-factor-pairs-worked0","kind":"worked","src":"stop:factor-pairs#worked0","title":"Worked out — Factors come in pairs: Every factor has a partner","body":"How many factors does 24 have?: Test 1, 2, 3… only up to the number whose square is at most 24. Which number is that? → 4 · How many of 1 to 4 divide 24 exactly? Each one starts a pair → 4 · Two factors in every pair → 8","cta":"Watch it step by step","level":4,"route":"#/stop/factor-pairs"},"idea-factor-pairs-case1":{"id":"idea-factor-pairs-case1","kind":"idea","src":"stop:factor-pairs#case1","title":"Factors come in pairs: A square number","body":"One pair is a number times itself, like 6 × 6. That is only ONE factor, so count it once — and the total comes out odd.","cta":"See it worked","level":4,"route":"#/stop/factor-pairs"},"worked-factor-pairs-worked1":{"id":"worked-factor-pairs-worked1","kind":"worked","src":"stop:factor-pairs#worked1","title":"Worked out — Factors come in pairs: A square number","body":"How many factors does 36 have?: Test 1, 2, 3… only up to the number whose square is at most 36. Which number is that? → 6 · How many of 1 to 6 divide 36 exactly? Each one starts a pair → 5 · Two factors per pair — but 6 × 6 is one number twice, so count it once → 9","cta":"Watch it step by step","level":4,"route":"#/stop/factor-pairs"},"why-factor-pairs-why1":{"id":"why-factor-pairs-why1","kind":"why","src":"stop:factor-pairs#why1","title":"Why “Factors come in pairs” works","body":"The pairs meet in the middle. 1 × 36, 2 × 18, 3 × 12, 4 × 9, 6 × 6 — the small partner grows while the big one shrinks, and once you pass 6 (because 6 × 6 = 36) every pair would just be one you have already found, turned round. So you only ever test up to the number whose square is the target.","cta":"See why","level":4,"route":"#/stop/factor-pairs"},"why-factor-pairs-why2":{"id":"why-factor-pairs-why2","kind":"why","src":"stop:factor-pairs#why2","title":"Why “Factors come in pairs” works","body":"That also tells you when the count is odd. Two factors per pair — unless the number is a square, where one pair is the same number twice, like 6 × 6. Square numbers are the only numbers with an odd number of factors.","cta":"See why","level":4,"route":"#/stop/factor-pairs"},"algebra-factor-pairs-alg":{"id":"algebra-factor-pairs-alg","kind":"algebra","src":"stop:factor-pairs#alg","title":"The algebra behind “Factors come in pairs”","body":"d | n ⇔ (n ÷ d) | n ; test d ≤ √n only","cta":"See why","level":4,"route":"#/stop/factor-pairs"},"moment-factor-pairs-beat2":{"id":"moment-factor-pairs-beat2","kind":"moment","src":"story:factor-pairs#beat2","badge":{"id":"story","label":"A story"},"title":"Planting the orchard — on the notepad","body":"Mira: Keep going: 3 rows of 12, 4 rows of 9… 4 × 9 = 36","cta":"Read the story","level":4,"route":"#/stop/factor-pairs"},"moral-factor-pairs-beat5":{"id":"moral-factor-pairs-beat5","kind":"moral","src":"story:factor-pairs#beat5","badge":{"id":"story","label":"A story"},"title":"Mira, in “Planting the orchard”","body":"Five pairs, but 6 × 6 is one number twice. So 36 has nine factors.","cta":"Read the story","level":4,"route":"#/stop/factor-pairs"},"try-factor-pairs-L4":{"id":"try-factor-pairs-L4","kind":"try","level":4,"src":"try:factor-pairs@4/1#0","title":"Factors come in pairs — your turn","route":"#/stop/factor-pairs","cta":"Practise this stop","play":{"q":"How many factors does 13 have?","opts":["2","3","1"],"after":"Find factors in pairs: test 1, 2, 3… and every one that divides gives you its partner too. Stop when the number times itself passes the target."}},"hook-multiples-hook":{"id":"hook-multiples-hook","kind":"hook","src":"stop:multiples#hook","title":"Can you? — The next multiple","body":"Eggs come in boxes of 6. What is the smallest number of eggs over 50 you can buy in whole boxes?","cta":"Find out how","level":4,"route":"#/stop/multiples"},"worked-multiples-worked0":{"id":"worked-multiples-worked0","kind":"worked","src":"stop:multiples#worked0","title":"Worked out — The next multiple: Some left over","body":"What is the first multiple of 6 bigger than 50?: 50 ÷ 6 — how many whole 6s fit? → 8 · Take one group more → 9 · 9 × 6 → 54","cta":"Watch it step by step","level":4,"route":"#/stop/multiples"},"why-multiples-why2":{"id":"why-multiples-why2","kind":"why","src":"stop:multiples#why2","title":"Why “The next multiple” works","body":"Multiples and factors are two views of one fact. 54 is a multiple of 6 exactly because 6 is a factor of 54.","cta":"See why","level":4,"route":"#/stop/multiples"},"moment-multiples-beat4":{"id":"moment-multiples-beat4","kind":"moment","src":"story:multiples#beat4","badge":{"id":"story","label":"A story"},"title":"Boxes of eggs — on the notepad","body":"Nova: So one box more. 8 + 1 = 9","cta":"Read the story","level":4,"route":"#/stop/multiples"},"try-multiples-L4":{"id":"try-multiples-L4","kind":"try","level":4,"src":"try:multiples@4/2#0","title":"The next multiple — your turn","route":"#/stop/multiples","cta":"Practise this stop","play":{"q":"What is the first multiple of 12 bigger than 114?","opts":["120","9","10"],"after":"Divide to see how many whole groups fit, then take one group more."}},"hook-divisible-2-5-10-hook":{"id":"hook-divisible-2-5-10-hook","kind":"hook","src":"stop:divisible-2-5-10#hook","title":"Can you? — Tests for 2, 5 and 10","body":"Does 3,475 split into fives? You only need to look at one digit.","cta":"Find out how","level":4,"route":"#/stop/divisible-2-5-10"},"worked-divisible-2-5-10-worked0":{"id":"worked-divisible-2-5-10-worked0","kind":"worked","src":"stop:divisible-2-5-10#worked0","title":"Worked out — Tests for 2, 5 and 10: Divisible by 2","body":"Is 1,358 divisible by 2?: The last digit of 1,358 → 8 · The test for 2: is the last digit even? → Yes","cta":"Watch it step by step","level":4,"route":"#/stop/divisible-2-5-10"},"worked-divisible-2-5-10-worked1":{"id":"worked-divisible-2-5-10-worked1","kind":"worked","src":"stop:divisible-2-5-10#worked1","title":"Worked out — Tests for 2, 5 and 10: Divisible by 5","body":"Is 3,475 divisible by 5?: The last digit of 3,475 → 5 · The test for 5: is the last digit 0 or 5? → Yes","cta":"Watch it step by step","level":4,"route":"#/stop/divisible-2-5-10"},"worked-divisible-2-5-10-worked2":{"id":"worked-divisible-2-5-10-worked2","kind":"worked","src":"stop:divisible-2-5-10#worked2","title":"Worked out — Tests for 2, 5 and 10: Divisible by 10","body":"Is 2,345 divisible by 10?: The last digit of 2,345 → 5 · The test for 10: is the last digit 0? → No","cta":"Watch it step by step","level":4,"route":"#/stop/divisible-2-5-10"},"why-divisible-2-5-10-why2":{"id":"why-divisible-2-5-10-why2","kind":"why","src":"stop:divisible-2-5-10#why2","title":"Why “Tests for 2, 5 and 10” works","body":"This is why the tests are so quick: the rest of the number is already taken care of, however long it is.","cta":"See why","level":4,"route":"#/stop/divisible-2-5-10"},"moment-divisible-2-5-10-beat2":{"id":"moment-divisible-2-5-10-beat2","kind":"moment","src":"story:divisible-2-5-10#beat2","badge":{"id":"story","label":"A story"},"title":"Bracelets of five — on the notepad","body":"Ines: No need. 3,470 is a pile of tens, and every ten is two fives. 3470 ÷ 5 = 694","cta":"Read the story","level":4,"route":"#/stop/divisible-2-5-10"},"try-divisible-2-5-10-L4":{"id":"try-divisible-2-5-10-L4","kind":"try","level":4,"src":"try:divisible-2-5-10@4/2#0","title":"Tests for 2, 5 and 10 — your turn","route":"#/stop/divisible-2-5-10","cta":"Practise this stop","play":{"q":"Is 9,928 divisible by 2?","opts":["Yes","No"],"after":"Look at the last digit only. Even for 2; 0 or 5 for 5; 0 for 10."}},"trick-all-from-nine-idea":{"id":"trick-all-from-nine-idea","kind":"trick","src":"stop:all-from-nine#idea","title":"Taking from 1000","body":"Take every digit from 9, except the last one, which you take from 10. 1000 is 999 + 1. Taking a number from 999 never borrows, because no digit is bigger than 9: 999 − 357 = 642.","cta":"Learn the trick","level":4,"route":"#/stop/all-from-nine"},"story-all-from-nine-open":{"id":"story-all-from-nine-open","kind":"story","src":"story:all-from-nine#open","badge":{"id":"story","label":"A story"},"title":"A thousand points","body":"Pip needs 1000 points for a prize kite, and has 357 so far. — with Ines and Pip.","art":"art/s-shop.webp","cta":"Read the story","level":4,"route":"#/stop/all-from-nine"},"hook-all-from-nine-hook":{"id":"hook-all-from-nine-hook","kind":"hook","src":"stop:all-from-nine#hook","title":"Can you? — Taking from 1000","body":"1000 − 357 — without a single borrow.","cta":"Find out how","level":4,"route":"#/stop/all-from-nine"},"idea-all-from-nine-case0":{"id":"idea-all-from-nine-case0","kind":"idea","src":"stop:all-from-nine#case0","title":"Taking from 1000: From 1000","body":"Three digits: the first two come from 9, the last one from 10. No borrowing anywhere.","cta":"See it worked","level":4,"route":"#/stop/all-from-nine"},"worked-all-from-nine-worked0":{"id":"worked-all-from-nine-worked0","kind":"worked","src":"stop:all-from-nine#worked0","title":"Worked out — Taking from 1000: From 1000","body":"1000 − 357: 9 − 3 (first digit) → 6 · 9 − 5 → 4 · 10 − 7 (last digit) → 3 · Read the digits → 643","cta":"Watch it step by step","level":4,"route":"#/stop/all-from-nine"},"idea-all-from-nine-case1":{"id":"idea-all-from-nine-case1","kind":"idea","src":"stop:all-from-nine#case1","title":"Taking from 1000: From 10000","body":"One more zero means one more digit. Still every digit from 9 except the last, which comes from 10.","cta":"See it worked","level":4,"route":"#/stop/all-from-nine"},"worked-all-from-nine-worked1":{"id":"worked-all-from-nine-worked1","kind":"worked","src":"stop:all-from-nine#worked1","title":"Worked out — Taking from 1000: From 10000","body":"10000 − 4618: 9 − 4 (first digit) → 5 · 9 − 6 → 3 · 9 − 1 → 8 · 10 − 8 (last digit) → 2 · Read the digits → 5382","cta":"Watch it step by step","level":4,"route":"#/stop/all-from-nine"},"idea-all-from-nine-case2":{"id":"idea-all-from-nine-case2","kind":"idea","src":"stop:all-from-nine#case2","title":"Taking from 1000: A shorter number","body":"Only three digits to take from four places? Put a 0 in front first — 0357 — and that 0 from 9 gives a 9.","cta":"See it worked","level":4,"route":"#/stop/all-from-nine"},"worked-all-from-nine-worked2":{"id":"worked-all-from-nine-worked2","kind":"worked","src":"stop:all-from-nine#worked2","title":"Worked out — Taking from 1000: A shorter number","body":"10000 − 357: 9 − 0 (first digit) → 9 · 9 − 3 → 6 · 9 − 5 → 4 · 10 − 7 (last digit) → 3 · Read the digits → 9643","cta":"Watch it step by step","level":4,"route":"#/stop/all-from-nine"},"why-all-from-nine-why1":{"id":"why-all-from-nine-why1","kind":"why","src":"stop:all-from-nine#why1","title":"Why “Taking from 1000” works","body":"Then add back the 1 — which is the same as taking the LAST digit from 10 instead of 9. 643.","cta":"See why","level":4,"route":"#/stop/all-from-nine"},"why-all-from-nine-why2":{"id":"why-all-from-nine-why2","kind":"why","src":"stop:all-from-nine#why2","title":"Why “Taking from 1000” works","body":"From 10000 it is the same with four digits: 10000 is 9999 + 1. If the number you take away is shorter, like 357, write it as 0357 first — that front 0 comes from 9 as a 9, so 10000 − 357 = 9643.","cta":"See why","level":4,"route":"#/stop/all-from-nine"},"algebra-all-from-nine-alg":{"id":"algebra-all-from-nine-alg","kind":"algebra","src":"stop:all-from-nine#alg","title":"The algebra behind “Taking from 1000”","body":"1000 − n = (999 − n) + 1","cta":"See why","level":4,"route":"#/stop/all-from-nine"},"sutra-all-from-nine-sutra":{"id":"sutra-all-from-nine-sutra","kind":"sutra","src":"stop:all-from-nine#sutra","title":"Nikhilam Navataścaramaṁ Daśataḥ","body":"“all from nine and the last from ten” — the sutra behind Taking from 1000.","cta":"Open the stop","level":4,"route":"#/stop/all-from-nine"},"moment-all-from-nine-beat3":{"id":"moment-all-from-nine-beat3","kind":"moment","src":"story:all-from-nine#beat3","badge":{"id":"story","label":"A story"},"title":"A thousand points — on the notepad","body":"Pip: Next: 9 take away 5. 9 − 5 = 4","cta":"Read the story","level":4,"route":"#/stop/all-from-nine"},"moral-all-from-nine-beat5":{"id":"moral-all-from-nine-beat5","kind":"moral","src":"story:all-from-nine#beat5","badge":{"id":"story","label":"A story"},"title":"Pip, in “A thousand points”","body":"Six, four, three. 643 to go — no borrowing at all!","cta":"Read the story","level":4,"route":"#/stop/all-from-nine"},"try-all-from-nine-L4":{"id":"try-all-from-nine-L4","kind":"try","level":4,"src":"try:all-from-nine@4/1#0","title":"Taking from 1000 — your turn","route":"#/stop/all-from-nine","cta":"Practise this stop","play":{"q":"1000 − 476 = ?","opts":["524","5","2"],"after":"Take every digit from 9, except the last one, which you take from 10."}},"trick-decimal-places-idea":{"id":"trick-decimal-places-idea","kind":"trick","src":"stop:decimal-places#idea","title":"Tenths and hundredths","body":"Each place after the point is worth a tenth of the place before it: tenths, then hundredths, then thousandths. Moving one place left always makes a digit worth ten times more: ones, tens, hundreds. So moving one place RIGHT makes it worth ten times less — and the pattern does not stop at the ones.","cta":"Learn the trick","level":4,"route":"#/stop/decimal-places"},"story-decimal-places-open":{"id":"story-decimal-places-open","kind":"story","src":"story:decimal-places#open","badge":{"id":"story","label":"A story"},"title":"The ribbon stall","body":"At the market, Pip buys 3.47 metres of blue ribbon for a kite tail. — with Rafi and Pip.","art":"art/s-market.webp","cta":"Read the story","level":4,"route":"#/stop/decimal-places"},"hook-decimal-places-hook":{"id":"hook-decimal-places-hook","kind":"hook","src":"stop:decimal-places#hook","title":"Can you? — Tenths and hundredths","body":"In 3.47, is the 7 worth seven? Seventy? Something much smaller?","cta":"Find out how","level":4,"route":"#/stop/decimal-places"},"idea-decimal-places-case0":{"id":"idea-decimal-places-case0","kind":"idea","src":"stop:decimal-places#case0","title":"Tenths and hundredths: What a digit is worth","body":"Count the places after the point: one place is tenths, two is hundredths. A 7 two places along is only 7 hundredths.","cta":"See it worked","level":4,"route":"#/stop/decimal-places"},"worked-decimal-places-worked0":{"id":"worked-decimal-places-worked0","kind":"worked","src":"stop:decimal-places#worked0","title":"Worked out — Tenths and hundredths: What a digit is worth","body":"What is the 7 worth in 3.47?: How many places after the point is the 7? → 2 · So it is worth → 0.07","cta":"Watch it step by step","level":4,"route":"#/stop/decimal-places"},"idea-decimal-places-case1":{"id":"idea-decimal-places-case1","kind":"idea","src":"stop:decimal-places#case1","title":"Tenths and hundredths: Build the number","body":"Now the other way: ones before the point, then each place after it in turn — tenths first, then hundredths.","cta":"See it worked","level":4,"route":"#/stop/decimal-places"},"worked-decimal-places-worked1":{"id":"worked-decimal-places-worked1","kind":"worked","src":"stop:decimal-places#worked1","title":"Worked out — Tenths and hundredths: Build the number","body":"3 ones, 4 tenths, 7 hundredths: The ones go before the point → 3 · 4 tenths — place 1 after the point → 0.4 · 7 hundredths — place 2 after the point → 0.07 · Put them together → 3.47","cta":"Watch it step by step","level":4,"route":"#/stop/decimal-places"},"why-decimal-places-why1":{"id":"why-decimal-places-why1","kind":"why","src":"stop:decimal-places#why1","title":"Why “Tenths and hundredths” works","body":"One step right of the ones is tenths: a whole cut into 10. One more step is hundredths: a whole cut into 100. The decimal point is just a marker that says \"the ones are here\".","cta":"See why","level":4,"route":"#/stop/decimal-places"},"why-decimal-places-why2":{"id":"why-decimal-places-why2","kind":"why","src":"stop:decimal-places#why2","title":"Why “Tenths and hundredths” works","body":"So 3.47 is 3 ones, 4 tenths and 7 hundredths. The 7 is worth 7 hundredths, 0.07 — less than one tenth, even though 7 looks bigger than 4.","cta":"See why","level":4,"route":"#/stop/decimal-places"},"algebra-decimal-places-alg":{"id":"algebra-decimal-places-alg","kind":"algebra","src":"stop:decimal-places#alg","title":"The algebra behind “Tenths and hundredths”","body":"a.bcd = a + b/10 + c/100 + d/1000","cta":"See why","level":4,"route":"#/stop/decimal-places"},"moment-decimal-places-beat3":{"id":"moment-decimal-places-beat3","kind":"moment","src":"story:decimal-places#beat3","badge":{"id":"story","label":"A story"},"title":"The ribbon stall — on the notepad","body":"Rafi: First place after the point is tenths: 4 tenths of a metre. 4 ÷ 10 = 0.4","cta":"Read the story","level":4,"route":"#/stop/decimal-places"},"moral-decimal-places-beat5":{"id":"moral-decimal-places-beat5","kind":"moral","src":"story:decimal-places#beat5","badge":{"id":"story","label":"A story"},"title":"Pip, in “The ribbon stall”","body":"So the place matters more than the digit. 347 hundredths of a metre in all.","cta":"Read the story","level":4,"route":"#/stop/decimal-places"},"try-decimal-places-L4":{"id":"try-decimal-places-L4","kind":"try","level":4,"src":"try:decimal-places@4/1#0","title":"Tenths and hundredths — your turn","route":"#/stop/decimal-places","cta":"Practise this stop","play":{"q":"4 ones, 1 tenths = ?","opts":["4.1","4","0.1"],"after":"Each place after the point is worth a tenth of the place before it: tenths, then hundredths, then thousandths."}},"trick-times-ten-decimals-idea":{"id":"trick-times-ten-decimals-idea","kind":"trick","src":"stop:times-ten-decimals#idea","title":"× and ÷ by 10, 100, 1000","body":"The point stays still; the digits move one place for every zero — left to multiply, right to divide. Times 10 makes every digit worth ten times more, and \"ten times more\" is exactly one place to the left. So every digit slides one place left: 3.47 × 10 = 34.7.","cta":"Learn the trick","level":4,"route":"#/stop/times-ten-decimals"},"story-times-ten-decimals-open":{"id":"story-times-ten-decimals-open","kind":"story","src":"story:times-ten-decimals#open","badge":{"id":"story","label":"A story"},"title":"A hundred tickets","body":"A ferry ticket costs 2.35 coins. The school needs 100 tickets. — with Kwame and Dax.","art":"art/s-harbour.webp","cta":"Read the story","level":4,"route":"#/stop/times-ten-decimals"},"hook-times-ten-decimals-hook":{"id":"hook-times-ten-decimals-hook","kind":"hook","src":"stop:times-ten-decimals#hook","title":"Can you? — × and ÷ by 10, 100, 1000","body":"3.47 × 100 — where does the point go?","cta":"Find out how","level":4,"route":"#/stop/times-ten-decimals"},"idea-times-ten-decimals-case0":{"id":"idea-times-ten-decimals-case0","kind":"idea","src":"stop:times-ten-decimals#case0","title":"× and ÷ by 10, 100, 1000: Multiplying","body":"Times makes every digit worth more, so they all slide left — one place for every zero.","cta":"See it worked","level":4,"route":"#/stop/times-ten-decimals"},"worked-times-ten-decimals-worked0":{"id":"worked-times-ten-decimals-worked0","kind":"worked","src":"stop:times-ten-decimals#worked0","title":"Worked out — × and ÷ by 10, 100, 1000: Multiplying","body":"3.47 × 100: How many zeros in 100? → 2 · Slide every digit 2 places left (bigger) → 347","cta":"Watch it step by step","level":4,"route":"#/stop/times-ten-decimals"},"idea-times-ten-decimals-case1":{"id":"idea-times-ten-decimals-case1","kind":"idea","src":"stop:times-ten-decimals#case1","title":"× and ÷ by 10, 100, 1000: Multiplying past the digits","body":"When the digits slide further left than there are decimal places, zeros fill the empty places before the point.","cta":"See it worked","level":4,"route":"#/stop/times-ten-decimals"},"worked-times-ten-decimals-worked1":{"id":"worked-times-ten-decimals-worked1","kind":"worked","src":"stop:times-ten-decimals#worked1","title":"Worked out — × and ÷ by 10, 100, 1000: Multiplying past the digits","body":"5.2 × 1000: How many zeros in 1000? → 3 · Slide every digit 3 places left (bigger) → 5200","cta":"Watch it step by step","level":4,"route":"#/stop/times-ten-decimals"},"idea-times-ten-decimals-case2":{"id":"idea-times-ten-decimals-case2","kind":"idea","src":"stop:times-ten-decimals#case2","title":"× and ÷ by 10, 100, 1000: Dividing","body":"Divide makes every digit worth less, so they slide right — and zeros hold the empty places just after the point.","cta":"See it worked","level":4,"route":"#/stop/times-ten-decimals"},"worked-times-ten-decimals-worked2":{"id":"worked-times-ten-decimals-worked2","kind":"worked","src":"stop:times-ten-decimals#worked2","title":"Worked out — × and ÷ by 10, 100, 1000: Dividing","body":"52 ÷ 1000: How many zeros in 1000? → 3 · Slide every digit 3 places right (smaller) → 0.052","cta":"Watch it step by step","level":4,"route":"#/stop/times-ten-decimals"},"why-times-ten-decimals-why1":{"id":"why-times-ten-decimals-why1","kind":"why","src":"stop:times-ten-decimals#why1","title":"Why “× and ÷ by 10, 100, 1000” works","body":"× 100 is × 10 twice, so the digits slide two places: 347. If the digits run out, zeros hold the empty places: 5.2 × 1000 = 5200. Dividing is the same slide the other way — 52 ÷ 1000 slides three places right, to 0.052, with zeros holding the empty places.","cta":"See why","level":4,"route":"#/stop/times-ten-decimals"},"why-times-ten-decimals-why2":{"id":"why-times-ten-decimals-why2","kind":"why","src":"stop:times-ten-decimals#why2","title":"Why “× and ÷ by 10, 100, 1000” works","body":"People say \"move the point\", and on paper it looks the same. But it is really the digits that move: the point always sits just after the ones, and it is the ones that change.","cta":"See why","level":4,"route":"#/stop/times-ten-decimals"},"algebra-times-ten-decimals-alg":{"id":"algebra-times-ten-decimals-alg","kind":"algebra","src":"stop:times-ten-decimals#alg","title":"The algebra behind “× and ÷ by 10, 100, 1000”","body":"x × 10ᵏ shifts every digit k places left; x ÷ 10ᵏ shifts them k places right","cta":"See why","level":4,"route":"#/stop/times-ten-decimals"},"moment-times-ten-decimals-beat4":{"id":"moment-times-ten-decimals-beat4","kind":"moment","src":"story:times-ten-decimals#beat4","badge":{"id":"story","label":"A story"},"title":"A hundred tickets — on the notepad","body":"Dax: The 2 goes to the hundreds, 3 to the tens, 5 to the ones: 235. 2.35 × 100 = 235","cta":"Read the story","level":4,"route":"#/stop/times-ten-decimals"},"moral-times-ten-decimals-beat5":{"id":"moral-times-ten-decimals-beat5","kind":"moral","src":"story:times-ten-decimals#beat5","badge":{"id":"story","label":"A story"},"title":"Kwame, in “A hundred tickets”","body":"And back again: slide them two places right.","cta":"Read the story","level":4,"route":"#/stop/times-ten-decimals"},"try-times-ten-decimals-L4":{"id":"try-times-ten-decimals-L4","kind":"try","level":4,"src":"try:times-ten-decimals@4/1#0","title":"× and ÷ by 10, 100, 1000 — your turn","route":"#/stop/times-ten-decimals","cta":"Practise this stop","play":{"q":"4.9 ÷ 100 = ?","opts":["0.049","2","0.050"],"after":"The point stays still; the digits move one place for every zero — left to multiply, right to divide."}},"idea-pictogram-total-case0":{"id":"idea-pictogram-total-case0","kind":"idea","src":"stop:pictogram-total#case0","title":"Reading a pictogram: Whole stars","body":"Read the key first. Every star is worth the same, so count the stars and times by the key.","cta":"See it worked","level":4,"route":"#/stop/pictogram-total"},"why-pictogram-total-why1":{"id":"why-pictogram-total-why1","kind":"why","src":"stop:pictogram-total#why1","title":"Why “Reading a pictogram” works","body":"So counting stars is counting bags, and bags of 4 are counted in fours: 5 stars is 5 × 4. A half star is half a bag — half of 4 is 2 — which is why the key always matters more than the stars.","cta":"See why","level":4,"route":"#/stop/pictogram-total"},"moment-pictogram-total-beat3":{"id":"moment-pictogram-total-beat3","kind":"moment","src":"story:pictogram-total#beat3","badge":{"id":"story","label":"A story"},"title":"The prize board — on the notepad","body":"Pip: And the half star is half a bag. 4 ÷ 2 = 2","cta":"Read the story","level":4,"route":"#/stop/pictogram-total"},"idea-bar-compare-case0":{"id":"idea-bar-compare-case0","kind":"idea","src":"stop:bar-compare#case0","title":"Bar charts: how many more?: Each line is 1","body":"Read across from the top of each bar, then take the smaller from the bigger.","cta":"See it worked","level":4,"route":"#/stop/bar-compare"},"why-bar-compare-why1":{"id":"why-bar-compare-why1","kind":"why","src":"stop:bar-compare#why1","title":"Why “Bar charts: how many more?” works","body":"\"How many more\" is a gap. Read across from the top of each bar to the numbers on the side, and the gap between the two tops is the difference: bigger take away smaller.","cta":"See why","level":4,"route":"#/stop/bar-compare"},"moment-bar-compare-beat4":{"id":"moment-bar-compare-beat4","kind":"moment","src":"story:bar-compare#beat4","badge":{"id":"story","label":"A story"},"title":"The ride vote — on the notepad","body":"Theo: The gap between the two tops is the difference. 34 − 21 = 13","cta":"Read the story","level":4,"route":"#/stop/bar-compare"},"trick-line-graph-read-idea":{"id":"trick-line-graph-read-idea","kind":"trick","src":"stop:line-graph-read#idea","title":"Reading a line graph","body":"Go up from the time to the line, then straight across to the scale. A line graph shows something that changes over time. Time runs along the bottom; the amount goes up the side. Each dot is one reading, and the line joins them in order.","cta":"Learn the trick","level":4,"route":"#/stop/line-graph-read"},"story-line-graph-read-open":{"id":"story-line-graph-read-open","kind":"story","src":"story:line-graph-read#open","badge":{"id":"story","label":"A story"},"title":"The hot afternoon","body":"The stadium screen shows a line graph of the temperature. At 11 o’clock the line is at 20 degrees; at noon it is at 24. — with Mira and Dax.","art":"art/s-stadium.webp","cta":"Read the story","level":4,"route":"#/stop/line-graph-read"},"hook-line-graph-read-hook":{"id":"hook-line-graph-read-hook","kind":"hook","src":"stop:line-graph-read#hook","title":"Can you? — Reading a line graph","body":"The line climbs all morning. How warm was it at 11?","cta":"Find out how","level":4,"route":"#/stop/line-graph-read"},"idea-line-graph-read-case0":{"id":"idea-line-graph-read-case0","kind":"idea","src":"stop:line-graph-read#case0","title":"Reading a line graph: Read one value","body":"Go up from the time to the dot, then across to the side. Each small gap is 2 degrees.","cta":"See it worked","level":4,"route":"#/stop/line-graph-read"},"idea-line-graph-read-case1":{"id":"idea-line-graph-read-case1","kind":"idea","src":"stop:line-graph-read#case1","title":"Reading a line graph: How much warmer?","body":"Read both times, then take the smaller from the bigger — the difference is the gap between the two dots.","cta":"See it worked","level":4,"route":"#/stop/line-graph-read"},"idea-line-graph-read-case2":{"id":"idea-line-graph-read-case2","kind":"idea","src":"stop:line-graph-read#case2","title":"Reading a line graph: Halfway between","body":"There is no dot there, but the line joins the two readings — halfway along is halfway between them.","cta":"See it worked","level":4,"route":"#/stop/line-graph-read"},"why-line-graph-read-why1":{"id":"why-line-graph-read-why1","kind":"why","src":"stop:line-graph-read#why1","title":"Why “Reading a line graph” works","body":"To read a value, go up from the time until you hit the line, then across to the side. Count the small gaps from the nearest number you know — here each gap is 2 degrees.","cta":"See why","level":4,"route":"#/stop/line-graph-read"},"why-line-graph-read-why2":{"id":"why-line-graph-read-why2","kind":"why","src":"stop:line-graph-read#why2","title":"Why “Reading a line graph” works","body":"Because the line joins the dots, a temperature that rose steadily from 20 at 11 o'clock to 24 at noon was about 22 at half past 11 — halfway along the line is halfway between the two readings.","cta":"See why","level":4,"route":"#/stop/line-graph-read"},"algebra-line-graph-read-alg":{"id":"algebra-line-graph-read-alg","kind":"algebra","src":"stop:line-graph-read#alg","title":"The algebra behind “Reading a line graph”","body":"value between two readings a and b, halfway along = (a + b) ÷ 2","cta":"See why","level":4,"route":"#/stop/line-graph-read"},"moment-line-graph-read-beat4":{"id":"moment-line-graph-read-beat4","kind":"moment","src":"story:line-graph-read#beat4","badge":{"id":"story","label":"A story"},"title":"The hot afternoon — on the notepad","body":"Dax: Half of that is 2. 4 ÷ 2 = 2","cta":"Read the story","level":4,"route":"#/stop/line-graph-read"},"moral-line-graph-read-beat6":{"id":"moral-line-graph-read-beat6","kind":"moral","src":"story:line-graph-read#beat6","badge":{"id":"story","label":"A story"},"title":"Dax, in “The hot afternoon”","body":"Twenty-two degrees. Up, across, and read.","cta":"Read the story","level":4,"route":"#/stop/line-graph-read"},"trick-work-backwards-idea":{"id":"trick-work-backwards-idea","kind":"trick","src":"stop:work-backwards#idea","title":"Work backwards","body":"When you know how a story ENDS, start there and undo each thing that happened, last one first. The story runs forwards: start → give some away → get some → end. You know the end but not the start. So walk the story the other way: the last thing that happened is the first thing you undo.","cta":"Learn the trick","level":4,"route":"#/stop/work-backwards"},"story-work-backwards-open":{"id":"story-work-backwards-open","kind":"story","src":"story:work-backwards#open","badge":{"id":"story","label":"A story"},"title":"The sticker swap","body":"Pip had some stickers. He gave 6 to his sister, got 10 more at a swap, then gave half of what he had to Theo. Now he has 14. — with Pip and Theo.","art":"art/s-room.webp","cta":"Read the story","level":4,"route":"#/stop/work-backwards"},"idea-work-backwards-case0":{"id":"idea-work-backwards-case0","kind":"idea","src":"stop:work-backwards#case0","title":"Work backwards: Gave some, got some","body":"Only adding and taking away: undo each one with its opposite, from the end.","cta":"See it worked","level":4,"route":"#/stop/work-backwards"},"idea-work-backwards-case1":{"id":"idea-work-backwards-case1","kind":"idea","src":"stop:work-backwards#case1","title":"Work backwards: Halves and doubles","body":"A half is undone by doubling, a double by halving — still last thing first.","cta":"See it worked","level":4,"route":"#/stop/work-backwards"},"idea-work-backwards-case2":{"id":"idea-work-backwards-case2","kind":"idea","src":"stop:work-backwards#case2","title":"Work backwards: Half, and then some more","body":"Two things in one: undo the \"more\" first, because it happened last, then double.","cta":"See it worked","level":4,"route":"#/stop/work-backwards"},"why-work-backwards-why1":{"id":"why-work-backwards-why1","kind":"why","src":"stop:work-backwards#why1","title":"Why “Work backwards” works","body":"Every event has an opposite that cancels it. Giving 7 away is undone by adding 7 back. Halving is undone by doubling. \"Half, then 3 more\" is two things, so undo the 3 first (it happened last), then double.","cta":"See why","level":4,"route":"#/stop/work-backwards"},"algebra-work-backwards-alg":{"id":"algebra-work-backwards-alg","kind":"algebra","src":"stop:work-backwards#alg","title":"The algebra behind “Work backwards”","body":"if x → f → g → end, then x = f⁻¹(g⁻¹(end))","cta":"See why","level":4,"route":"#/stop/work-backwards"},"moral-work-backwards-beat6":{"id":"moral-work-backwards-beat6","kind":"moral","src":"story:work-backwards#beat6","badge":{"id":"story","label":"A story"},"title":"Pip, in “The sticker swap”","body":"We do! I started with 24 — I just undid it backwards, last thing first.","cta":"Read the story","level":4,"route":"#/stop/work-backwards"},"try-work-backwards-L4":{"id":"try-work-backwards-L4","kind":"try","level":4,"src":"try:work-backwards@4/1#0","title":"Work backwards — your turn","route":"#/stop/work-backwards","cta":"Practise this stop","play":{"q":"Lena had some stickers. Then Lena gave 8 away and then got 3 more. That left 9. How many stickers did Lena have at the start?","opts":["14","6","15"],"after":"When you know how a story ENDS, start there and undo each thing that happened, last one first."}},"trick-guess-check-improve-idea":{"id":"trick-guess-check-improve-idea","kind":"trick","src":"stop:guess-check-improve#idea","title":"Guess, check, improve","body":"Make a sensible guess, check it, and let \"too big\" or \"too small\" tell you which way to move. Some problems are hard to work out forwards but easy to CHECK. If someone says \"is it 20?\", you can multiply and see. So guess — and every wrong guess still tells you something: too big means go down, too small means go up.","cta":"Learn the trick","level":4,"route":"#/stop/guess-check-improve"},"story-guess-check-improve-open":{"id":"story-guess-check-improve-open","kind":"story","src":"story:guess-check-improve#open","badge":{"id":"story","label":"A story"},"title":"Two page numbers","body":"Dax opens a library book in the middle. Nova covers the page numbers and says: \"They multiply to make 506. What do they add up to?\" — with Dax and Nova.","art":"art/s-library.webp","cta":"Read the story","level":4,"route":"#/stop/guess-check-improve"},"hook-guess-check-improve-hook":{"id":"hook-guess-check-improve-hook","kind":"hook","src":"stop:guess-check-improve#hook","title":"Can you? — Guess, check, improve","body":"Two numbers next to each other multiply to make 506. What do they add up to?","cta":"Find out how","level":4,"route":"#/stop/guess-check-improve"},"idea-guess-check-improve-case0":{"id":"idea-guess-check-improve-case0","kind":"idea","src":"stop:guess-check-improve#case0","title":"Guess, check, improve: Two numbers in a row","body":"Their product is just above a square, so start near the square root and step up or down.","cta":"See it worked","level":4,"route":"#/stop/guess-check-improve"},"worked-guess-check-improve-worked0":{"id":"worked-guess-check-improve-worked0","kind":"worked","src":"stop:guess-check-improve#worked0","title":"Worked out — Guess, check, improve: Two numbers in a row","body":"Two whole numbers next to each other on the number line multiply to make 506. What do they add up to?: Guess: 20 × 21 → 420 · Too small, so go up. Which smaller number works? → 22 · Add them: 22 + 23 → 45","cta":"Watch it step by step","level":4,"route":"#/stop/guess-check-improve"},"idea-guess-check-improve-case1":{"id":"idea-guess-check-improve-case1","kind":"idea","src":"stop:guess-check-improve#case1","title":"Guess, check, improve: A total and a product","body":"Start with an even split; if the product is too big, spread the two numbers further apart.","cta":"See it worked","level":4,"route":"#/stop/guess-check-improve"},"worked-guess-check-improve-worked1":{"id":"worked-guess-check-improve-worked1","kind":"worked","src":"stop:guess-check-improve#worked1","title":"Worked out — Guess, check, improve: A total and a product","body":"Two whole numbers add up to 15 and multiply to make 44. What is the bigger number?: Guess an even split: 7 × 8 → 56 · Too big — spread them apart. Which smaller number works? → 4 · The bigger one: 15 − 4 → 11","cta":"Watch it step by step","level":4,"route":"#/stop/guess-check-improve"},"idea-guess-check-improve-case2":{"id":"idea-guess-check-improve-case2","kind":"idea","src":"stop:guess-check-improve#case2","title":"Guess, check, improve: Three in a row","body":"Three numbers in a row multiply to about the middle one cubed — guess with a round number, then improve.","cta":"See it worked","level":4,"route":"#/stop/guess-check-improve"},"worked-guess-check-improve-worked2":{"id":"worked-guess-check-improve-worked2","kind":"worked","src":"stop:guess-check-improve#worked2","title":"Worked out — Guess, check, improve: Three in a row","body":"Three whole numbers in a row multiply to make 2730. What do they add up to?: Guess: 15 × 16 × 17 → 4080 · Too big, so go down. Which smallest number works? → 13 · Add them: 13 + 14 + 15 → 42","cta":"Watch it step by step","level":4,"route":"#/stop/guess-check-improve"},"why-guess-check-improve-why1":{"id":"why-guess-check-improve-why1","kind":"why","src":"stop:guess-check-improve#why1","title":"Why “Guess, check, improve” works","body":"A good guess saves steps. Two numbers next to each other multiply to a little more than a square, so 20 × 21 = 420 is a nearby, easy first try. 506 is bigger, so go up — and 22 × 23 = 506 lands it.","cta":"See why","level":4,"route":"#/stop/guess-check-improve"},"why-guess-check-improve-why2":{"id":"why-guess-check-improve-why2","kind":"why","src":"stop:guess-check-improve#why2","title":"Why “Guess, check, improve” works","body":"When two numbers have a fixed total, their product is biggest when they are equal and shrinks as they spread apart (try 5 × 5, 4 × 6, 3 × 7 — 25, 24, 21). So if a product is too big, move the numbers further apart. Guessing is not cheating; improving the guess is the method.","cta":"See why","level":4,"route":"#/stop/guess-check-improve"},"algebra-guess-check-improve-alg":{"id":"algebra-guess-check-improve-alg","kind":"algebra","src":"stop:guess-check-improve#alg","title":"The algebra behind “Guess, check, improve”","body":"guess g → check f(g) → too big: go down · too small: go up","cta":"See why","level":4,"route":"#/stop/guess-check-improve"},"moment-guess-check-improve-beat3":{"id":"moment-guess-check-improve-beat3","kind":"moment","src":"story:guess-check-improve#beat3","badge":{"id":"story","label":"A story"},"title":"Two page numbers — on the notepad","body":"Dax: Then 25 and 26. 25 × 26 = 650","cta":"Read the story","level":4,"route":"#/stop/guess-check-improve"},"moral-guess-check-improve-beat5":{"id":"moral-guess-check-improve-beat5","kind":"moral","src":"story:guess-check-improve#beat5","badge":{"id":"story","label":"A story"},"title":"Dax, in “Two page numbers”","body":"Bang on. Three guesses, and each one pointed the way.","cta":"Read the story","level":4,"route":"#/stop/guess-check-improve"},"try-guess-check-improve-L4":{"id":"try-guess-check-improve-L4","kind":"try","level":4,"src":"try:guess-check-improve@4/1#0","title":"Guess, check, improve — your turn","route":"#/stop/guess-check-improve","cta":"Practise this stop","play":{"q":"Two whole numbers next to each other on the number line multiply to make 90. What do they add up to?","opts":["19","110","9"],"after":"Make a sensible guess, check it, and let \"too big\" or \"too small\" tell you which way to move."}},"trick-make-a-table-idea":{"id":"trick-make-a-table-idea","kind":"trick","src":"stop:make-a-table#idea","title":"Make a table","body":"Put the numbers in a table, one row at a time, and watch the pattern in the rows — it shows you the answer. A story with things changing week by week is hard to hold in your head. A table holds it for you: one row for each week, one column for each person. You only ever work out the next row from the one above.","cta":"Learn the trick","level":4,"route":"#/stop/make-a-table"},"story-make-a-table-open":{"id":"story-make-a-table-open","kind":"story","src":"story:make-a-table#open","badge":{"id":"story","label":"A story"},"title":"The savings race","body":"Rafi has 30 coins and saves 4 a week. Ines has 6 coins but saves 10 a week. When will they have the same? — with Rafi and Ines.","art":"art/s-market.webp","cta":"Read the story","level":4,"route":"#/stop/make-a-table"},"hook-make-a-table-hook":{"id":"hook-make-a-table-hook","kind":"hook","src":"stop:make-a-table#hook","title":"Can you? — Make a table","body":"Rafi has 30 and saves 4 a week. Ines has 6 and saves 10 a week. When do they have the same?","cta":"Find out how","level":4,"route":"#/stop/make-a-table"},"idea-make-a-table-case0":{"id":"idea-make-a-table-case0","kind":"idea","src":"stop:make-a-table#case0","title":"Make a table: When are they equal?","body":"Fill two rows, see how much the gap shrinks each week, and divide.","cta":"See it worked","level":4,"route":"#/stop/make-a-table"},"worked-make-a-table-worked0":{"id":"worked-make-a-table-worked0","kind":"worked","src":"stop:make-a-table#worked0","title":"Worked out — Make a table: When are they equal?","body":"Rafi has 30 coins in a money box and adds 4 every week. Ines has 6 and adds 10 every week. After how many weeks will they have the same amount?: After 1 week, Rafi has → 34 · After 1 week, Ines has → 16 · The gap started at 24. Each week it closes by → 6 · Weeks to close a gap of 24 → 4","cta":"Watch it step by step","level":4,"route":"#/stop/make-a-table"},"idea-make-a-table-case1":{"id":"idea-make-a-table-case1","kind":"idea","src":"stop:make-a-table#case1","title":"Make a table: When does a total pass?","body":"Keep a running total in its own column, and stop on the first row that reaches it.","cta":"See it worked","level":4,"route":"#/stop/make-a-table"},"worked-make-a-table-worked1":{"id":"worked-make-a-table-worked1","kind":"worked","src":"stop:make-a-table#worked1","title":"Worked out — Make a table: When does a total pass?","body":"On day 1, Maya reads 5 pages. Every day after that, Maya reads 3 more pages than the day before. On which day does the total number of pages read first reach 60?: Total for days 1, 2 and 3 → 24 · Keep the table going. How many pages are read on the day the total reaches 60? → 20 · Which day is that? → 6","cta":"Watch it step by step","level":4,"route":"#/stop/make-a-table"},"idea-make-a-table-case2":{"id":"idea-make-a-table-case2","kind":"idea","src":"stop:make-a-table#case2","title":"Make a table: Counting the ways","body":"One row for each number of rulers; keep the rows that leave the right money for pencils.","cta":"See it worked","level":4,"route":"#/stop/make-a-table"},"worked-make-a-table-worked2":{"id":"worked-make-a-table-worked2","kind":"worked","src":"stop:make-a-table#worked2","title":"Worked out — Make a table: Counting the ways","body":"Pencils cost 3 coins each and rulers cost 5 coins each. Omar spends exactly 52 coins and buys at least one of each. How many different ways could Omar do it?: Fewest rulers that leave a multiple of 3 coins → 2 · Most rulers that still leave money for a pencil → 8 · The rulers that work go up 3 at a time. How many ways? → 3","cta":"Watch it step by step","level":4,"route":"#/stop/make-a-table"},"why-make-a-table-why1":{"id":"why-make-a-table-why1","kind":"why","src":"stop:make-a-table#why1","title":"Why “Make a table” works","body":"After a row or two, look at what changes. Rafi is 24 ahead at the start; every week Ines gains 10 and Rafi gains 4, so the gap shrinks by 6. You do not need fifty rows — 24 ÷ 6 = 4 weeks.","cta":"See why","level":4,"route":"#/stop/make-a-table"},"why-make-a-table-why2":{"id":"why-make-a-table-why2","kind":"why","src":"stop:make-a-table#why2","title":"Why “Make a table” works","body":"Tables also stop you missing anything when you count ways. Buying pencils and rulers to spend exactly 40? Write one row for each number of rulers and see which rows work. A tidy list cannot skip a case.","cta":"See why","level":4,"route":"#/stop/make-a-table"},"algebra-make-a-table-alg":{"id":"algebra-make-a-table-alg","kind":"algebra","src":"stop:make-a-table#alg","title":"The algebra behind “Make a table”","body":"gap ÷ (change in the gap each row) = rows needed","cta":"See why","level":4,"route":"#/stop/make-a-table"},"moment-make-a-table-beat3":{"id":"moment-make-a-table-beat3","kind":"moment","src":"story:make-a-table#beat3","badge":{"id":"story","label":"A story"},"title":"The savings race — on the notepad","body":"Rafi: Look at the gap, though. It started at 24… 30 − 6 = 24","cta":"Read the story","level":4,"route":"#/stop/make-a-table"},"moral-make-a-table-beat5":{"id":"moral-make-a-table-beat5","kind":"moral","src":"story:make-a-table#beat5","badge":{"id":"story","label":"A story"},"title":"Rafi, in “The savings race”","body":"So the rows will close the gap in 24 ÷ 6 weeks. No need to write all of them.","cta":"Read the story","level":4,"route":"#/stop/make-a-table"},"try-make-a-table-L4":{"id":"try-make-a-table-L4","kind":"try","level":4,"src":"try:make-a-table@4/1#0","title":"Make a table — your turn","route":"#/stop/make-a-table","cta":"Practise this stop","play":{"q":"Jai has 23 coins in a money box and adds 4 every week. Zoe has 8 and adds 7 every week. After how many weeks will they have the same amount?","opts":["5","27","15"],"after":"Put the numbers in a table, one row at a time, and watch the pattern in the rows — it shows you the answer."}},"trick-bar-model-idea":{"id":"trick-bar-model-idea","kind":"trick","src":"stop:bar-model#idea","title":"Draw the bars","body":"Draw each amount as a bar, make the bars the same size, and the total shares out into equal bars. Draw Suki's shells as a bar. Pip's bar is the same length plus an extra piece of 14. Both bars together are 52. Now cut off the extra piece: 52 − 14 = 38 is two EQUAL bars, so one bar is 19.","cta":"Learn the trick","level":4,"route":"#/stop/bar-model"},"story-bar-model-open":{"id":"story-bar-model-open","kind":"story","src":"story:bar-model#open","badge":{"id":"story","label":"A story"},"title":"Shells on the beach","body":"Suki and Pip collected 52 shells between them. Pip collected 14 more than Suki. — with Suki and Pip.","art":"art/s-beach.webp","cta":"Read the story","level":4,"route":"#/stop/bar-model"},"hook-bar-model-hook":{"id":"hook-bar-model-hook","kind":"hook","src":"stop:bar-model#hook","title":"Can you? — Draw the bars","body":"Suki and Pip have 52 shells. Pip has 14 more than Suki. How many has Pip — without guessing?","cta":"Find out how","level":4,"route":"#/stop/bar-model"},"idea-bar-model-case0":{"id":"idea-bar-model-case0","kind":"idea","src":"stop:bar-model#case0","title":"Draw the bars: A total and a difference","body":"Cut the extra piece off, and what is left is two equal bars.","cta":"See it worked","level":4,"route":"#/stop/bar-model"},"worked-bar-model-worked0":{"id":"worked-bar-model-worked0","kind":"worked","src":"stop:bar-model#worked0","title":"Worked out — Draw the bars: A total and a difference","body":"Pip and Suki have 52 shells altogether. Pip has 14 more than Suki. How many does Pip have?: Cut off the extra: 52 − 14 → 38 · Two equal bars: 38 ÷ 2 → 19 · Pip is one bar and the extra: 19 + 14 → 33","cta":"Watch it step by step","level":4,"route":"#/stop/bar-model"},"idea-bar-model-case1":{"id":"idea-bar-model-case1","kind":"idea","src":"stop:bar-model#case1","title":"Draw the bars: Times as many","body":"Draw the bigger amount as several copies of the smaller bar, then count the bars.","cta":"See it worked","level":4,"route":"#/stop/bar-model"},"worked-bar-model-worked1":{"id":"worked-bar-model-worked1","kind":"worked","src":"stop:bar-model#worked1","title":"Worked out — Draw the bars: Times as many","body":"Femi has 3 times as many stamps as Gita. Together they have 48. How many does Femi have?: How many equal bars? 3 + 1 → 4 · One bar: 48 ÷ 4 → 12 · Femi has 3 bars: 3 × 12 → 36","cta":"Watch it step by step","level":4,"route":"#/stop/bar-model"},"idea-bar-model-case2":{"id":"idea-bar-model-case2","kind":"idea","src":"stop:bar-model#case2","title":"Draw the bars: Give some, then equal","body":"Giving closes the gap from BOTH ends, so it closes twice the amount given.","cta":"See it worked","level":4,"route":"#/stop/bar-model"},"worked-bar-model-worked2":{"id":"worked-bar-model-worked2","kind":"worked","src":"stop:bar-model#worked2","title":"Worked out — Draw the bars: Give some, then equal","body":"Asha has 3 times as many cards as Ben. When Asha gives Ben 10 cards, they have the same number. How many cards did Asha have at the start?: How many bars is the gap? 3 − 1 → 2 · Giving 10 closes the gap from both ends: 10 + 10 → 20 · One bar: 20 ÷ 2 → 10 · Asha started with 3 bars: 3 × 10 → 30","cta":"Watch it step by step","level":4,"route":"#/stop/bar-model"},"why-bar-model-why1":{"id":"why-bar-model-why1","kind":"why","src":"stop:bar-model#why1","title":"Why “Draw the bars” works","body":"\"Three times as many\" is three equal bars against one. Together that is four equal bars, so share the total by 4. The bars turn a puzzle in words into a sharing sum.","cta":"See why","level":4,"route":"#/stop/bar-model"},"why-bar-model-why2":{"id":"why-bar-model-why2","kind":"why","src":"stop:bar-model#why2","title":"Why “Draw the bars” works","body":"When one person gives some to another and they end up equal, look at the gap. If Asha has 3 bars and Ben 1, the gap is 2 bars. Giving 10 away makes Asha 10 smaller AND Ben 10 bigger, so it closes a gap of 20 — and 2 bars = 20 means one bar is 10.","cta":"See why","level":4,"route":"#/stop/bar-model"},"algebra-bar-model-alg":{"id":"algebra-bar-model-alg","kind":"algebra","src":"stop:bar-model#alg","title":"The algebra behind “Draw the bars”","body":"bigger = (total + difference) ÷ 2 · one bar = total ÷ number of bars","cta":"See why","level":4,"route":"#/stop/bar-model"},"moment-bar-model-beat3":{"id":"moment-bar-model-beat3","kind":"moment","src":"story:bar-model#beat3","badge":{"id":"story","label":"A story"},"title":"Shells on the beach — on the notepad","body":"Suki: Now the two bars are the same, so share it equally. 38 ÷ 2 = 19","cta":"Read the story","level":4,"route":"#/stop/bar-model"},"moral-bar-model-beat5":{"id":"moral-bar-model-beat5","kind":"moral","src":"story:bar-model#beat5","badge":{"id":"story","label":"A story"},"title":"Suki, in “Shells on the beach”","body":"Check the other way: take my 19 from the 52 and see what is left for you. The bars did the thinking.","cta":"Read the story","level":4,"route":"#/stop/bar-model"},"try-bar-model-L4":{"id":"try-bar-model-L4","kind":"try","level":4,"src":"try:bar-model@4/1#0","title":"Draw the bars — your turn","route":"#/stop/bar-model","cta":"Practise this stop","play":{"q":"Zoe has 2 times as many beads as Ela. Together they have 15. How many does Zoe have?","opts":["10","3","5"],"after":"Draw each amount as a bar, make the bars the same size, and the total shares out into equal bars."}},"trick-units-digit-cycles-idea":{"id":"trick-units-digit-cycles-idea","kind":"trick","src":"stop:units-digit-cycles#idea","title":"Ride the cycle","body":"Last digits go round in a cycle. Find how long the cycle is, then see where your number lands in it. The last digit of a product depends only on the last digits you multiply. So for powers of 7, only the 7 matters each time: 7, then 7 × 7 = 49 (ends 9), then 9 × 7 = 63 (ends 3), then 3 × 7 = 21 (ends 1), then 1 × 7 = 7 again. The last digits go 7, 9, 3, 1 and round again, for ever.","cta":"Learn the trick","level":4,"route":"#/stop/units-digit-cycles"},"story-units-digit-cycles-open":{"id":"story-units-digit-cycles-open","kind":"story","src":"story:units-digit-cycles#open","badge":{"id":"story","label":"A story"},"title":"The last digit","body":"In the school hall, Kwame writes a challenge: what is the last digit of 7 multiplied by itself 50 times? — with Kwame and Ines.","art":"art/s-hall.webp","cta":"Read the story","level":4,"route":"#/stop/units-digit-cycles"},"idea-units-digit-cycles-case0":{"id":"idea-units-digit-cycles-case0","kind":"idea","src":"stop:units-digit-cycles#case0","title":"Ride the cycle: A repeating pattern","body":"Find the block that repeats, then the remainder tells you the place in the block.","cta":"See it worked","level":4,"route":"#/stop/units-digit-cycles"},"idea-units-digit-cycles-case1":{"id":"idea-units-digit-cycles-case1","kind":"idea","src":"stop:units-digit-cycles#case1","title":"Ride the cycle: The last digit of a power","body":"The last digits of the powers repeat, so it is a pattern too — find its cycle first.","cta":"See it worked","level":4,"route":"#/stop/units-digit-cycles"},"idea-units-digit-cycles-case2":{"id":"idea-units-digit-cycles-case2","kind":"idea","src":"stop:units-digit-cycles#case2","title":"Ride the cycle: The last digit of a sum","body":"Find each last digit with its own cycle, add, and keep only the last digit.","cta":"See it worked","level":4,"route":"#/stop/units-digit-cycles"},"why-units-digit-cycles-why1":{"id":"why-units-digit-cycles-why1","kind":"why","src":"stop:units-digit-cycles#why1","title":"Why “Ride the cycle” works","body":"A cycle of 4 means powers 4, 8, 12, … all land on the last place, 1. To find where power 50 lands, divide by 4: 50 = 12 × 4 + 2, so it lands on the second place, 9. A remainder of 0 means the very end of the cycle.","cta":"See why","level":4,"route":"#/stop/units-digit-cycles"},"algebra-units-digit-cycles-alg":{"id":"algebra-units-digit-cycles-alg","kind":"algebra","src":"stop:units-digit-cycles#alg","title":"The algebra behind “Ride the cycle”","body":"nth item of a cycle of length L = item number (n ÷ L remainder), 0 meaning L","cta":"See why","level":4,"route":"#/stop/units-digit-cycles"},"moral-units-digit-cycles-beat5":{"id":"moral-units-digit-cycles-beat5","kind":"moral","src":"story:units-digit-cycles#beat5","badge":{"id":"story","label":"A story"},"title":"Ines, in “The last digit”","body":"The second ending in the cycle is the 9 of 49 — take away the tens.","cta":"Read the story","level":4,"route":"#/stop/units-digit-cycles"},"try-units-digit-cycles-L4":{"id":"try-units-digit-cycles-L4","kind":"try","level":4,"src":"try:units-digit-cycles@4/1#0","title":"Ride the cycle — your turn","route":"#/stop/units-digit-cycles","cta":"Practise this stop","play":{"q":"A row of digits repeats the same block for ever: 9, 6, 1, 5, 2, 9, 6, 1, 5, 2, 9, 6, 1, 5, 2, … What is digit number 98 in the row?","opts":["1","5","3"],"after":"Last digits go round in a cycle. Find how long the cycle is, then see where your number lands in it."}},"word-24-hour-clock":{"id":"word-24-hour-clock","kind":"word","src":"dictionary:24-hour clock#def","title":"24-hour clock","body":"Telling the time with hours from 00 to 23, so no a.m. or p.m. is needed. For example: 3:30 p.m. = 15:30.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-24-hour-clock":{"id":"wordq-24-hour-clock","kind":"wordq","src":"dictionary:24-hour clock#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “3:30 p.m. = 15:30.”","opts":["24-hour clock","exchange","enlargement"],"after":"24-hour clock: Telling the time with hours from 00 to 23, so no a.m. or p.m. is needed."},"level":4},"word-area":{"id":"word-area","kind":"word","src":"dictionary:area#def","title":"area","body":"How much flat surface a shape covers, counted in squares. For example: 6 cm by 4 cm: 24 cm².","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-area":{"id":"wordq-area","kind":"wordq","src":"dictionary:area#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “6 cm by 4 cm: 24 cm².”","opts":["area","vertex","simplify"],"after":"area: How much flat surface a shape covers, counted in squares."},"level":4},"word-associative":{"id":"word-associative","kind":"word","src":"dictionary:associative#def","title":"associative","body":"Giving the same answer however the numbers are grouped with brackets — true of adding and multiplying. For example: (2 + 3) + 4 = 2 + (3 + 4).","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-associative":{"id":"wordq-associative","kind":"wordq","src":"dictionary:associative#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “(2 + 3) + 4 = 2 + (3 + 4).”","opts":["associative","translation","rotation"],"after":"associative: Giving the same answer however the numbers are grouped with brackets — true of adding and multiplying."},"level":4},"word-axis":{"id":"word-axis","kind":"word","src":"dictionary:axis#def","title":"axis","body":"One of the two number lines on a graph: x goes across, y goes up. Plural: axes. For example: The point (4, 1) is 4 along the x one.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-axis":{"id":"wordq-axis","kind":"wordq","src":"dictionary:axis#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “The point (4, 1) is 4 along the x one.”","opts":["axis","identity","pie chart"],"after":"axis: One of the two number lines on a graph: x goes across, y goes up. Plural: axes."},"level":4},"word-clockwise":{"id":"word-clockwise","kind":"word","src":"dictionary:clockwise#def","title":"clockwise","body":"Turning the same way as the hands of a clock. For example: A quarter turn this way takes 12 round to 3.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-clockwise":{"id":"wordq-clockwise","kind":"wordq","src":"dictionary:clockwise#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “A quarter turn this way takes 12 round to 3.”","opts":["clockwise","direct proportion","factor pair"],"after":"clockwise: Turning the same way as the hands of a clock."},"level":4},"word-coordinates":{"id":"word-coordinates","kind":"word","src":"dictionary:coordinates#def","title":"coordinates","body":"A pair of numbers (x, y) that give a point’s position: across first, then up. For example: (3, 2) is 3 across and 2 up.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-coordinates":{"id":"wordq-coordinates","kind":"wordq","src":"dictionary:coordinates#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “(3, 2) is 3 across and 2 up.”","opts":["coordinates","decimal point","square centimetre"],"after":"coordinates: A pair of numbers (x, y) that give a point’s position: across first, then up."},"level":4},"word-decimal":{"id":"word-decimal","kind":"word","src":"dictionary:decimal#def","title":"decimal","body":"A number written with a point, where the digits after the point are tenths, hundredths and so on. For example: 3.25 = 3 + 2 tenths + 5 hundredths.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-decimal":{"id":"wordq-decimal","kind":"wordq","src":"dictionary:decimal#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “3.25 = 3 + 2 tenths + 5 hundredths.”","opts":["decimal","protractor","index laws"],"after":"decimal: A number written with a point, where the digits after the point are tenths, hundredths and so on."},"level":4},"word-decimal-place":{"id":"word-decimal-place","kind":"word","src":"dictionary:decimal place#def","title":"decimal place","body":"One position after the point: the first is tenths, the second hundredths, the third thousandths. For example: 3.142 has three.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-decimal-place":{"id":"wordq-decimal-place","kind":"wordq","src":"dictionary:decimal place#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “3.142 has three.”","opts":["decimal place","coefficient","identity"],"after":"decimal place: One position after the point: the first is tenths, the second hundredths, the third thousandths."},"level":4},"word-decimal-point":{"id":"word-decimal-point","kind":"word","src":"dictionary:decimal point#def","title":"decimal point","body":"The dot that separates the whole-number part from the tenths. For example: In 12.5 it sits between the 2 and the 5.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-decimal-point":{"id":"wordq-decimal-point","kind":"wordq","src":"dictionary:decimal point#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “In 12.5 it sits between the 2 and the 5.”","opts":["decimal point","integer","composite number"],"after":"decimal point: The dot that separates the whole-number part from the tenths."},"level":4},"word-diagonal":{"id":"word-diagonal","kind":"word","src":"dictionary:diagonal#def","title":"diagonal","body":"A straight line joining two corners of a shape that are not next to each other. For example: A rectangle has 2.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-diagonal":{"id":"wordq-diagonal","kind":"wordq","src":"dictionary:diagonal#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “A rectangle has 2.”","opts":["diagonal","ratio","halve"],"after":"diagonal: A straight line joining two corners of a shape that are not next to each other."},"level":4},"word-division":{"id":"word-division","kind":"word","src":"dictionary:division#def","title":"division","body":"Sharing into equal groups, or finding how many equal groups fit. Sign: ÷. For example: 12 ÷ 3 = 4.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-division":{"id":"wordq-division","kind":"wordq","src":"dictionary:division#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “12 ÷ 3 = 4.”","opts":["division","range","net"],"after":"division: Sharing into equal groups, or finding how many equal groups fit. Sign: ÷."},"level":4},"word-equilateral-triangle":{"id":"word-equilateral-triangle","kind":"word","src":"dictionary:equilateral triangle#def","title":"equilateral triangle","body":"A three-sided shape with all its sides the same length and every angle 60°. For example: Sides 5 cm, 5 cm and 5 cm.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-equilateral-triangle":{"id":"wordq-equilateral-triangle","kind":"wordq","src":"dictionary:equilateral triangle#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “Sides 5 cm, 5 cm and 5 cm.”","opts":["equilateral triangle","equivalent fractions","universal set"],"after":"equilateral triangle: A three-sided shape with all its sides the same length and every angle 60°."},"level":4},"word-factor":{"id":"word-factor","kind":"word","src":"dictionary:factor#def","title":"factor","body":"A whole number that divides into another exactly, leaving nothing over. For example: 12 can be divided exactly by 1, 2, 3, 4, 6 and 12.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-factor":{"id":"wordq-factor","kind":"wordq","src":"dictionary:factor#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “12 can be divided exactly by 1, 2, 3, 4, 6 and 12.”","opts":["factor","common denominator","number bond"],"after":"factor: A whole number that divides into another exactly, leaving nothing over."},"level":4},"word-factor-pair":{"id":"word-factor-pair","kind":"word","src":"dictionary:factor pair#def","title":"factor pair","body":"Two whole numbers that multiply together to make a given number. For example: 3 and 8 are one for 24, because 3 × 8 = 24.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-factor-pair":{"id":"wordq-factor-pair","kind":"wordq","src":"dictionary:factor pair#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “3 and 8 are one for 24, because 3 × 8 = 24.”","opts":["factor pair","decimal point","vertically and crosswise"],"after":"factor pair: Two whole numbers that multiply together to make a given number."},"level":4},"word-hundredth":{"id":"word-hundredth","kind":"word","src":"dictionary:hundredth#def","title":"hundredth","body":"One of a hundred equal parts: 1/100 or 0.01. For example: 1p is 0.01 of £1.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-hundredth":{"id":"wordq-hundredth","kind":"wordq","src":"dictionary:hundredth#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “1p is 0.01 of £1.”","opts":["hundredth","square number","compound measure"],"after":"hundredth: One of a hundred equal parts: 1/100 or 0.01."},"level":4},"word-hypotenuse":{"id":"word-hypotenuse","kind":"word","src":"dictionary:hypotenuse#def","title":"hypotenuse","body":"The longest side of a right-angled triangle, opposite the right angle. For example: In a 3, 4, 5 triangle it is 5.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-hypotenuse":{"id":"wordq-hypotenuse","kind":"wordq","src":"dictionary:hypotenuse#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “In a 3, 4, 5 triangle it is 5.”","opts":["hypotenuse","formula","probability"],"after":"hypotenuse: The longest side of a right-angled triangle, opposite the right angle."},"level":4},"word-isosceles-triangle":{"id":"word-isosceles-triangle","kind":"word","src":"dictionary:isosceles triangle#def","title":"isosceles triangle","body":"A three-sided shape with two sides the same length — and the two angles at their foot equal. For example: Sides 5 cm, 5 cm and 3 cm.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"word-kite":{"id":"word-kite","kind":"word","src":"dictionary:kite#def","title":"kite","body":"A four-sided shape with two pairs of equal sides that sit next to each other. For example: Sides 5, 5, 8 and 8 cm.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"word-line-graph":{"id":"word-line-graph","kind":"word","src":"dictionary:line graph#def","title":"line graph","body":"A graph that joins points with lines to show how something changes over time. For example: The temperature at 9, 10, 11 and 12 o’clock.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-line-graph":{"id":"wordq-line-graph","kind":"wordq","src":"dictionary:line graph#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “The temperature at 9, 10, 11 and 12 o’clock.”","opts":["line graph","simplest form","quarter"],"after":"line graph: A graph that joins points with lines to show how something changes over time."},"level":4},"word-mental-maths":{"id":"word-mental-maths","kind":"word","src":"dictionary:mental maths#def","title":"mental maths","body":"Working things out in your head, often with a shortcut, instead of on paper. For example: 25 × 16 = 100 × 4 = 400.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-mental-maths":{"id":"wordq-mental-maths","kind":"wordq","src":"dictionary:mental maths#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “25 × 16 = 100 × 4 = 400.”","opts":["mental maths","discount","factor pair"],"after":"mental maths: Working things out in your head, often with a shortcut, instead of on paper."},"level":4},"word-nikhilam":{"id":"word-nikhilam","kind":"word","src":"dictionary:nikhilam#def","title":"nikhilam","body":"The method “all from nine and the last from ten”: work with how far numbers are from 10, 100 or 1,000. For example: 1000 − 357: 9 − 3, 9 − 5, 10 − 7 → 643.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-nikhilam":{"id":"wordq-nikhilam","kind":"wordq","src":"dictionary:nikhilam#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “1000 − 357: 9 − 3, 9 − 5, 10 − 7 → 643.”","opts":["nikhilam","negative number","double"],"after":"nikhilam: The method “all from nine and the last from ten”: work with how far numbers are from 10, 100 or 1,000."},"level":4},"word-origin":{"id":"word-origin","kind":"word","src":"dictionary:origin#def","title":"origin","body":"The point (0, 0), where the two axes cross. For example: (0, 0).","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-origin":{"id":"wordq-origin","kind":"wordq","src":"dictionary:origin#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “(0, 0).”","opts":["origin","simplest form","cubic centimetre"],"after":"origin: The point (0, 0), where the two axes cross."},"level":4},"word-parallel":{"id":"word-parallel","kind":"word","src":"dictionary:parallel#def","title":"parallel","body":"Always the same distance apart, so they never meet however far they go. For example: The 2 rails of a railway track.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-parallel":{"id":"wordq-parallel","kind":"wordq","src":"dictionary:parallel#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “The 2 rails of a railway track.”","opts":["parallel","double","term-to-term rule"],"after":"parallel: Always the same distance apart, so they never meet however far they go."},"level":4},"word-pythagoras-theorem":{"id":"word-pythagoras-theorem","kind":"word","src":"dictionary:Pythagoras’ theorem#def","title":"Pythagoras’ theorem","body":"In a right-angled triangle, the square on the longest side equals the squares on the other two sides added together: a² + b² = c². (For 13–14.) For example: 3² + 4² = 9 + 16 = 25 = 5².","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-pythagoras-theorem":{"id":"wordq-pythagoras-theorem","kind":"wordq","src":"dictionary:Pythagoras’ theorem#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “3² + 4² = 9 + 16 = 25 = 5².”","opts":["Pythagoras’ theorem","median","denominator"],"after":"Pythagoras’ theorem: In a right-angled triangle, the square on the longest side equals the squares on the other two sides added together: a² + b² = c². (For 13–14.)"},"level":4},"word-quadrilateral":{"id":"word-quadrilateral","kind":"word","src":"dictionary:quadrilateral#def","title":"quadrilateral","body":"A flat shape with four straight sides. For example: Its angles add up to 360°.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"word-quotient":{"id":"word-quotient","kind":"word","src":"dictionary:quotient#def","title":"quotient","body":"The answer to a division. For example: In 20 ÷ 4 = 5 it is 5.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-quotient":{"id":"wordq-quotient","kind":"wordq","src":"dictionary:quotient#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “In 20 ÷ 4 = 5 it is 5.”","opts":["quotient","direct proportion","chance"],"after":"quotient: The answer to a division."},"level":4},"word-remainder":{"id":"word-remainder","kind":"word","src":"dictionary:remainder#def","title":"remainder","body":"What is left over when one number does not go exactly into another. For example: 17 ÷ 5 = 3, with 2 left over.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-remainder":{"id":"wordq-remainder","kind":"wordq","src":"dictionary:remainder#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “17 ÷ 5 = 3, with 2 left over.”","opts":["remainder","pentagon","integer"],"after":"remainder: What is left over when one number does not go exactly into another."},"level":4},"word-rhombus":{"id":"word-rhombus","kind":"word","src":"dictionary:rhombus#def","title":"rhombus","body":"A four-sided shape with all four sides equal — like a square pushed over. For example: All 4 sides 5 cm.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-rhombus":{"id":"wordq-rhombus","kind":"wordq","src":"dictionary:rhombus#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “All 4 sides 5 cm.”","opts":["rhombus","change","index laws"],"after":"rhombus: A four-sided shape with all four sides equal — like a square pushed over."},"level":4},"word-right-angled-triangle":{"id":"word-right-angled-triangle","kind":"word","src":"dictionary:right-angled triangle#def","title":"right-angled triangle","body":"A three-sided shape with one angle of exactly 90°. For example: Sides 3, 4 and 5 make one.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-right-angled-triangle":{"id":"wordq-right-angled-triangle","kind":"wordq","src":"dictionary:right-angled triangle#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “Sides 3, 4 and 5 make one.”","opts":["right-angled triangle","negative number","union"],"after":"right-angled triangle: A three-sided shape with one angle of exactly 90°."},"level":4},"word-rotation":{"id":"word-rotation","kind":"word","src":"dictionary:rotation#def","title":"rotation","body":"Turning a shape about a fixed point. For example: A quarter turn clockwise about (0, 0).","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-rotation":{"id":"wordq-rotation","kind":"wordq","src":"dictionary:rotation#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “A quarter turn clockwise about (0, 0).”","opts":["rotation","rounding","commutative"],"after":"rotation: Turning a shape about a fixed point."},"level":4},"word-scalene-triangle":{"id":"word-scalene-triangle","kind":"word","src":"dictionary:scalene triangle#def","title":"scalene triangle","body":"A three-sided shape with every side a different length. For example: Sides 4 cm, 6 cm and 7 cm.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-scalene-triangle":{"id":"wordq-scalene-triangle","kind":"wordq","src":"dictionary:scalene triangle#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “Sides 4 cm, 6 cm and 7 cm.”","opts":["scalene triangle","element","triangular number"],"after":"scalene triangle: A three-sided shape with every side a different length."},"level":4},"word-short-division":{"id":"word-short-division","kind":"word","src":"dictionary:short division#def","title":"short division","body":"A written method that shares one digit at a time, passing each remainder on to the next digit. For example: 96 ÷ 4: 9 ÷ 4 = 2 r 1, then 16 ÷ 4 = 4 → 24.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-short-division":{"id":"wordq-short-division","kind":"wordq","src":"dictionary:short division#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “96 ÷ 4: 9 ÷ 4 = 2 r 1, then 16 ÷ 4 = 4 → 24.”","opts":["short division","diameter","capacity"],"after":"short division: A written method that shares one digit at a time, passing each remainder on to the next digit."},"level":4},"word-simplest-form":{"id":"word-simplest-form","kind":"word","src":"dictionary:simplest form#def","title":"simplest form","body":"A fraction whose top and bottom share no factor except 1. For example: 3/4 is; 6/8 is not.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-simplest-form":{"id":"wordq-simplest-form","kind":"wordq","src":"dictionary:simplest form#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “3/4 is; 6/8 is not.”","opts":["simplest form","volume","coordinates"],"after":"simplest form: A fraction whose top and bottom share no factor except 1."},"level":4},"word-simplify":{"id":"word-simplify","kind":"word","src":"dictionary:simplify#def","title":"simplify","body":"Divide the top and bottom of a fraction by the same number, so it is written with smaller numbers. For example: 6/8 → 3/4, dividing both by 2.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-simplify":{"id":"wordq-simplify","kind":"wordq","src":"dictionary:simplify#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “6/8 → 3/4, dividing both by 2.”","opts":["simplify","identity","clockwise"],"after":"simplify: Divide the top and bottom of a fraction by the same number, so it is written with smaller numbers."},"level":4},"word-square":{"id":"word-square","kind":"word","src":"dictionary:square#def","title":"square","body":"A four-sided shape with all four sides equal and all four corners right angles. For example: One with 3 cm sides has perimeter 12 cm and area 9 cm².","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-square":{"id":"wordq-square","kind":"wordq","src":"dictionary:square#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “One with 3 cm sides has perimeter 12 cm and area 9 cm².”","opts":["square","index","expression"],"after":"square: A four-sided shape with all four sides equal and all four corners right angles."},"level":4},"word-standard-form":{"id":"word-standard-form","kind":"word","src":"dictionary:standard form#def","title":"standard form","body":"A way to write very big or very small numbers as a number from 1 up to (not including) 10, times a power of ten. For example: 32,000 = 3.2 × 10⁴.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-standard-form":{"id":"wordq-standard-form","kind":"wordq","src":"dictionary:standard form#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “32,000 = 3.2 × 10⁴.”","opts":["standard form","scalene triangle","outlier"],"after":"standard form: A way to write very big or very small numbers as a number from 1 up to (not including) 10, times a power of ten."},"level":4},"word-tenth":{"id":"word-tenth","kind":"word","src":"dictionary:tenth#def","title":"tenth","body":"One of ten equal parts: 1/10 or 0.1. For example: Three of them make 0.3.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-tenth":{"id":"wordq-tenth","kind":"wordq","src":"dictionary:tenth#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “Three of them make 0.3.”","opts":["tenth","right angle","union"],"after":"tenth: One of ten equal parts: 1/10 or 0.1."},"level":4},"word-translation":{"id":"word-translation","kind":"word","src":"dictionary:translation#def","title":"translation","body":"Sliding a shape to a new place without turning or flipping it. For example: 3 right and 2 up: (1, 1) → (4, 3).","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-translation":{"id":"wordq-translation","kind":"wordq","src":"dictionary:translation#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “3 right and 2 up: (1, 1) → (4, 3).”","opts":["translation","identity","casting out nines"],"after":"translation: Sliding a shape to a new place without turning or flipping it."},"level":4},"word-trapezium":{"id":"word-trapezium","kind":"word","src":"dictionary:trapezium#def","title":"trapezium","body":"A four-sided shape with exactly one pair of parallel sides. For example: Parallel sides 4 cm and 6 cm, height 3 cm: area 15 cm².","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-trapezium":{"id":"wordq-trapezium","kind":"wordq","src":"dictionary:trapezium#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “Parallel sides 4 cm and 6 cm, height 3 cm: area 15 cm².”","opts":["trapezium","inverse operation","compensation"],"after":"trapezium: A four-sided shape with exactly one pair of parallel sides."},"level":4},"word-triangle":{"id":"word-triangle","kind":"word","src":"dictionary:triangle#def","title":"triangle","body":"A flat shape with three straight sides and three corners. For example: Its angles always add to 180°.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":4},"wordq-triangle":{"id":"wordq-triangle","kind":"wordq","src":"dictionary:triangle#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “Its angles always add to 180°.”","opts":["triangle","like terms","speed"],"after":"triangle: A flat shape with three straight sides and three corners."},"level":4},"stone-vedic-all-from-nine":{"src":"journey:vedic/all-from-nine#0","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic","cta":"Walk the Vedic Maths Journey","id":"stone-vedic-all-from-nine","kind":"stone","title":"Taking away from 1000 — Nikhilam Navataścaramaṁ Daśataḥ","body":"To take a number from 1000 (or 10 000), take every digit from 9 — except the last one, which you take from 10.","level":4},"stone-vedic-all-from-nine-1":{"src":"journey:vedic/all-from-nine#1","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic","cta":"Walk the Vedic Maths Journey","id":"stone-vedic-all-from-nine-1","kind":"stone-step","title":"Taking away from 1000 (2 of 3)","body":"1000 − 357: 9 − 3 = 6, 9 − 5 = 4, 10 − 7 = 3. Answer 643. Not one borrow.","level":4},"stone-vedic-all-from-nine-2":{"src":"journey:vedic/all-from-nine#2","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic","cta":"Walk the Vedic Maths Journey","id":"stone-vedic-all-from-nine-2","kind":"stone-step","title":"Taking away from 1000 (3 of 3)","body":"Why: 1000 is 999 + 1. Taking any number from 999 never borrows, because no digit is bigger than 9. Adding back the 1 is the same as taking the last digit from 10 instead of 9.","level":4},"stone-try-vedic-all-from-nine":{"src":"journey:vedic/all-from-nine#gen0","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic","cta":"Walk the Vedic Maths Journey","id":"stone-try-vedic-all-from-nine","kind":"stone-try","title":"Taking away from 1000 — try it","play":{"q":"10000 − 4117 = ?","opts":["5883","5","8"],"after":"Subtracting with no borrowing"},"level":4}};
